        function getCachedBranches() {
            if (Array.isArray(branches) && branches.length > 0) {
                return branches;
            }
            try {
                const raw = localStorage.getItem(BRANCH_STORAGE_KEY);
                if (raw) {
                    const parsed = JSON.parse(raw);
                    if (Array.isArray(parsed)) {
                        return parsed;
                    }
                }
            } catch (error) {
            }
            return [];
        }
        
