        async function handleFileImport(event) {
            const file = event?.target?.files?.[0];
            if (!file) return;
            updateDataStatus('Importing data...', 'info');
            try {
                const text = await file.text();
                const payload = JSON.parse(text);
                if (Array.isArray(payload.clients) && payload.clients.length) {
                    await apiRequest('/clients', 'POST', payload.clients);
                }
                if (Array.isArray(payload.users) && payload.users.length) {
                    for (const user of payload.users) {
                        try {
                            await apiRequest('/users', 'POST', user);
                        } catch (error) {
                            console.warn('User import skipped:', error.message || error);
                        }
                    }
                }
                if (Array.isArray(payload.branches) && payload.branches.length) {
                    await apiRequest('/branches', 'POST', payload.branches);
                    await syncBranchesFromBackend(true);
                }
                if (Array.isArray(payload.distributors) && payload.distributors.length) {
                    await saveDistributors(payload.distributors);
                }
                if (Array.isArray(payload.products) && payload.products.length) {
                    await apiRequest('/products', 'POST', payload.products);
                }
                if (Array.isArray(payload.productImages) && payload.productImages.length) {
                    await apiRequest('/product_images', 'POST', payload.productImages);
                }
                updateDataStatus('✅ Import completed successfully.', 'success');
                await refreshAllData();
                await loadProductPhotos(true);
                renderProductPhotos();
            } catch (error) {
                console.error('handleFileImport error', error);
                updateDataStatus(`❌ ${error.message || 'Failed to import data.'}`, 'error');
            } finally {
                if (event?.target) event.target.value = '';
            }
        }
        
