        function convertFileToBase64Payload(file) {
            return new Promise((resolve, reject) => {
                try {
                    const reader = new FileReader();
                    reader.onload = () => {
                        resolve({
                            name: file.name,
                            type: file.type,
                            size: file.size,
                            data: reader.result
                        });
                    };
                    reader.onerror = () => reject(reader.error || new Error('Unable to read file'));
                    reader.readAsDataURL(file);
                } catch (error) {
                    reject(error);
                }
            });
        }
        
