        if (typeof applyAutoOrderSettings === 'function') applyAutoOrderSettings();
        if (typeof applySyncSettings === 'function') applySyncSettings();
        if (typeof loadStockOrders === 'function') loadStockOrders();
        if (typeof loadShopWarehouseSharing === 'function') loadShopWarehouseSharing();
