        function escHtml(str) {
            var d = document.createElement('div');
            d.textContent = str;
            return d.innerHTML;
        }

        async function loadPendingRegistrations() {
            var container = document.getElementById('pendingRegistrations');
            if (!container) return;
            container.innerHTML = '<p style="color: #888;">Loading...</p>';
            try {
                var res = await fetch('/api/admin/pending-registrations', { credentials: 'include' });
                if (!res.ok) { container.innerHTML = '<p style="color: #e74c3c;">Failed to load pending registrations.</p>'; return; }
                var data = await res.json();
                var users = data.registrations || data || [];
                if (!users || users.length === 0) {
                    container.innerHTML = '<p style="color: #27ae60;">No pending registrations.</p>';
                    return;
                }
                var roleLabels = { frontdesk: 'Front Desk', consultant: 'Consultant', dispenser: 'Dispenser', branch_manager: 'Branch Manager', finance: 'Finance', hr_manager: 'HR Manager', gm: 'General Manager', director: 'Director', mis: 'MIS', stock: 'Stock/Warehouse' };
                var html = '<table style="width:100%; border-collapse:collapse; font-size:0.9rem;"><thead><tr style="background:#f1f5f9;">';
                html += '<th style="padding:8px; text-align:left; border-bottom:2px solid #e2e8f0;">Name</th>';
                html += '<th style="padding:8px; text-align:left; border-bottom:2px solid #e2e8f0;">Username</th>';
                html += '<th style="padding:8px; text-align:left; border-bottom:2px solid #e2e8f0;">Position</th>';
                html += '<th style="padding:8px; text-align:left; border-bottom:2px solid #e2e8f0;">DOB</th>';
                html += '<th style="padding:8px; text-align:left; border-bottom:2px solid #e2e8f0;">Date</th>';
                html += '<th style="padding:8px; text-align:center; border-bottom:2px solid #e2e8f0;">Actions</th>';
                html += '</tr></thead><tbody>';
                users.forEach(function(u) {
                    var meta = {};
                    try { meta = typeof u.metadata === 'string' ? JSON.parse(u.metadata) : (u.metadata || {}); } catch(_) {}
                    var dob = escHtml(meta.dob || '-');
                    var roleLabel = escHtml(roleLabels[u.role] || u.role || '-');
                    var created = u.created_at ? escHtml(new Date(u.created_at).toLocaleDateString()) : '-';
                    var safeId = escHtml(u.id);
                    html += '<tr style="border-bottom:1px solid #e2e8f0;">';
                    html += '<td style="padding:8px;">' + escHtml(u.full_name || '-') + '</td>';
                    html += '<td style="padding:8px; font-family:monospace;">' + escHtml(u.username || '-') + '</td>';
                    html += '<td style="padding:8px;">' + roleLabel + '</td>';
                    html += '<td style="padding:8px;">' + dob + '</td>';
                    html += '<td style="padding:8px;">' + created + '</td>';
                    html += '<td style="padding:8px; text-align:center;">';
                    html += '<button class="btn btn-success" style="padding:4px 12px; font-size:0.8rem; margin-right:4px;" onclick="approveRegistration(\'' + safeId + '\')">Approve</button>';
                    html += '<button class="btn btn-danger" style="padding:4px 12px; font-size:0.8rem;" onclick="rejectRegistration(\'' + safeId + '\')">Reject</button>';
                    html += '</td></tr>';
                });
                html += '</tbody></table>';
                container.innerHTML = html;
            } catch (err) {
                container.innerHTML = '<p style="color: #e74c3c;">Error loading registrations.</p>';
            }
        }

        async function approveRegistration(userId) {
            if (!confirm('Approve this staff registration?')) return;
            try {
                var res = await fetch('/api/admin/approve-registration', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    credentials: 'include',
                    body: JSON.stringify({ userId: userId })
                });
                var data = await res.json();
                if (!res.ok) { alert(data.error || 'Approval failed.'); return; }
                alert('Registration approved successfully.');
                loadPendingRegistrations();
            } catch (err) { alert('Error: ' + err.message); }
        }

        async function rejectRegistration(userId) {
            if (!confirm('Reject and delete this staff registration? This cannot be undone.')) return;
            try {
                var res = await fetch('/api/admin/reject-registration', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    credentials: 'include',
                    body: JSON.stringify({ userId: userId })
                });
                var data = await res.json();
                if (!res.ok) { alert(data.error || 'Rejection failed.'); return; }
                alert('Registration rejected.');
                loadPendingRegistrations();
            } catch (err) { alert('Error: ' + err.message); }
        }

        async function refreshAllData() {
            const previousHash = lastDataHash;
            await loadData();
            loadBranches();
            
            // Check if data has changed and show notification
            if (previousHash && hasDataChanged()) {
                showDataUpdateNotification();
            }
            
            // Refresh current portal data if user is logged in
            if (currentUser) {
                if (currentPortal === 'consultant') {
                    await syncConsultantAppointments();
                    await displayClients({ skipLoad: true });
                    await displayFollowUps();
                    viewTodayAppointments();
                } else if (currentPortal === 'dispenser') {
                    await displayPrescriptions();
                } else if (currentPortal === 'stock') {
                    renderForecastList();
                    renderPurchaseOrders();
                    renderSupplierScorecard();
                    renderPlanInsights();
                    renderASNList();
                    renderQualityList();
                    renderPutawayQueue();
                    renderWarehouseCapacity();
                    renderReplenishmentSuggestions();
                    renderBranchRequestList();
                    updateBranchMetrics();
                    renderReturnsList();
                    renderRouteBoard();
                    renderInventoryAlerts();
                    renderReorderScenarioResults();
                    displayCountryStock();
                    displayWindhoekStock();
                    displayOndangwaStock();
                    displayDistributionHistory();
                } else if (currentPortal === 'mis') {
                    ensureMISPortalInitialized();
                    loadMISBranches();
                    await loadMISReceipts({ force: true });
                } else if (currentPortal === 'admin') {
                    loadUserList();
                    loadBranchListAdmin();
                    await populatePhotoProductSelect();
                    await loadProductPhotos();
                    renderProductPhotos();
                    loadAdminDistributorDirectory();
                }
            }
        }

        // Auto-refresh functionality
        function startAutoRefresh() {
            if (autoRefreshInterval) {
                clearInterval(autoRefreshInterval);
            }
            
            // Refresh every 30 seconds when user is logged in (reduced from 5s to prevent API spam)
            // Real-time updates should come from WebSocket/SSE, not polling
            autoRefreshInterval = setInterval(async () => {
                if (currentUser) {
                    try {
                        await refreshAllData();
                    } catch (error) {
                        // Silently handle errors to prevent console spam
                    }
                }
            }, 30000); // 30 seconds instead of 5 seconds
            
        }

        function stopAutoRefresh() {
            if (autoRefreshInterval) {
                clearInterval(autoRefreshInterval);
                autoRefreshInterval = null;
            }
        }

        // Show notification when data is updated
        function showDataUpdateNotification() {
            const notification = document.createElement('div');
            notification.style.cssText = `
                position: fixed;
                top: 20px;
                right: 20px;
                background: #27ae60;
                color: white;
                padding: 12px 20px;
                border-radius: 5px;
                box-shadow: 0 4px 6px rgba(0,0,0,0.1);
                z-index: 10000;
                font-size: 14px;
                animation: slideIn 0.3s ease-out;
            `;
            notification.innerHTML = '🔄 Data updated from another device';
            document.body.appendChild(notification);
            
            // Remove notification after 3 seconds
            setTimeout(() => {
                notification.style.animation = 'slideOut 0.3s ease-in';
                setTimeout(() => {
                    if (notification.parentNode) {
                        notification.parentNode.removeChild(notification);
                    }
                }, 300);
            }, 3000);
        }

        // Loading Indicator Utility Functions
        function showLoadingIndicator(element, message = 'Loading...') {
            if (!element) return null;
            
            const loadingId = 'loading_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
            const loadingEl = document.createElement('div');
            loadingEl.id = loadingId;
            loadingEl.className = 'loading-indicator';
            loadingEl.innerHTML = `
                <div class="loading-spinner"></div>
                <span>${message}</span>
            `;
            
            // Insert before element or replace content
            if (element.parentNode) {
                element.parentNode.insertBefore(loadingEl, element);
                element.style.display = 'none';
            } else {
                element.innerHTML = '';
                element.appendChild(loadingEl);
            }
            
            return loadingId;
        }
        
        function hideLoadingIndicator(element, loadingId = null) {
            if (!element) return;
            
            if (loadingId) {
                const loadingEl = document.getElementById(loadingId);
                if (loadingEl && loadingEl.parentNode) {
                    loadingEl.parentNode.removeChild(loadingEl);
                }
            } else {
                const loadingEl = element.querySelector('.loading-indicator');
                if (loadingEl) {
                    loadingEl.remove();
                }
            }
            
            element.style.display = '';
        }
        
        function showLoadingOverlay(message = 'Loading...') {
            const overlay = document.createElement('div');
            overlay.id = 'globalLoadingOverlay';
            overlay.className = 'loading-overlay';
            overlay.innerHTML = `
                <div class="loading-overlay-content">
                    <div class="loading-spinner"></div>
                    <div>${message}</div>
                </div>
            `;
            document.body.appendChild(overlay);
            return overlay;
        }
        
        function hideLoadingOverlay() {
            const overlay = document.getElementById('globalLoadingOverlay');
            if (overlay && overlay.parentNode) {
                overlay.parentNode.removeChild(overlay);
            }
        }
        
        function showInlineLoading(element, message = 'Loading...') {
            if (!element) return null;
            
            const originalContent = element.innerHTML;
            element.dataset.originalContent = originalContent;
            element.className = (element.className || '') + ' loading-inline';
            element.innerHTML = `
                <div class="loading-spinner"></div>
                <span>${message}</span>
            `;
            
            return () => {
                element.innerHTML = originalContent;
                element.className = element.className.replace(' loading-inline', '');
            };
        }

        // Data Validation Utility Functions
        function validateField(field, rules = {}) {
            const value = field.value ? field.value.trim() : '';
            const errors = [];
            
            // Required validation
            if (rules.required && !value) {
                errors.push(rules.requiredMessage || 'This field is required');
            }
            
            // Min length validation
            if (rules.minLength && value.length < rules.minLength) {
                errors.push(rules.minLengthMessage || `Must be at least ${rules.minLength} characters`);
            }
            
            // Max length validation
            if (rules.maxLength && value.length > rules.maxLength) {
                errors.push(rules.maxLengthMessage || `Must be no more than ${rules.maxLength} characters`);
            }
            
            // Pattern validation
            if (rules.pattern && value && !rules.pattern.test(value)) {
                errors.push(rules.patternMessage || 'Invalid format');
            }
            
            // Email validation
            if (rules.type === 'email' && value) {
                const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                if (!emailPattern.test(value)) {
                    errors.push('Please enter a valid email address');
                }
            }
            
            // Phone validation
            if (rules.type === 'phone' && value) {
                const phonePattern = /^[\d\s\-\+\(\)]+$/;
                if (!phonePattern.test(value) || value.replace(/\D/g, '').length < 8) {
                    errors.push('Please enter a valid phone number');
                }
            }
            
            // Number range validation
            if (rules.type === 'number' && value) {
                const num = parseFloat(value);
                if (isNaN(num)) {
                    errors.push('Please enter a valid number');
                } else {
                    if (rules.min !== undefined && num < rules.min) {
                        errors.push(`Must be at least ${rules.min}`);
                    }
                    if (rules.max !== undefined && num > rules.max) {
                        errors.push(`Must be no more than ${rules.max}`);
                    }
            }
            }
            
            return {
                isValid: errors.length === 0,
                errors: errors
            };
        }
        
        function showFieldValidation(field, isValid, message = '') {
            // Remove existing validation styling
            field.classList.remove('field-error', 'field-success');
            const existingError = field.parentNode?.querySelector('.field-error-message');
            if (existingError) {
                existingError.remove();
            }
            
            if (!isValid && message) {
                field.classList.add('field-error');
                const errorEl = document.createElement('div');
                errorEl.className = 'field-error-message';
                errorEl.textContent = message;
                errorEl.style.cssText = 'color: #ef4444; font-size: 0.85rem; margin-top: 4px;';
                if (field.parentNode) {
                    field.parentNode.appendChild(errorEl);
                }
            } else if (isValid) {
                field.classList.add('field-success');
            }
        }
        
        function validateForm(form, fieldRules = {}) {
            const errors = {};
            let isValid = true;
            
            Object.keys(fieldRules).forEach(fieldName => {
                const field = form.querySelector(`[name="${fieldName}"], #${fieldName}`);
                if (field) {
                    const validation = validateField(field, fieldRules[fieldName]);
                    if (!validation.isValid) {
                        isValid = false;
                        errors[fieldName] = validation.errors;
                        showFieldValidation(field, false, validation.errors[0]);
                    } else {
                        showFieldValidation(field, true);
                    }
                }
            });
            
            return {
                isValid: isValid,
                errors: errors
            };
        }

        // Show/hide real-time status indicator
        function showRealtimeStatus() {
            const status = document.getElementById('realtimeStatus');
            if (status) {
                status.style.display = 'block';
                status.className = 'realtime-status';
                status.innerHTML = '🔄 Real-time sync active';
            }
        }

        function hideRealtimeStatus() {
            const status = document.getElementById('realtimeStatus');
            if (status) {
                status.style.display = 'none';
            }
        }

        function updateRealtimeStatus(status) {
            const statusElement = document.getElementById('realtimeStatus');
            if (statusElement) {
                statusElement.className = `realtime-status ${status}`;
                switch(status) {
                    case 'offline':
                        statusElement.innerHTML = '❌ Connection lost';
                        break;
                    case 'syncing':
                        statusElement.innerHTML = '🔄 Syncing...';
                        break;
                    default:
                        statusElement.innerHTML = '🔄 Real-time sync active';
                }
            }
        }

        // Network synchronization test functions
        async function testNetworkSync() {
            try {
                updateRealtimeStatus('syncing');
                
                // Test API connectivity with fallback
                let response;
                let data;
                let connectedTo = 'Unknown';
                
                // Try primary API
                try {
                    response = await fetch(`${API_BASE}/clients`);
                    data = await response.json();
                    connectedTo = 'Primary Server';
                } catch (e1) {
                    // Try secondary local API if different
                    if (API_BASE_LOCAL !== API_BASE) {
                        try {
                            response = await fetch(`${API_BASE_LOCAL}/clients`);
                            data = await response.json();
                            connectedTo = 'Secondary Local Server';
                        } catch (e2) {
                            // Fall back to local storage
                            data = clients;
                            connectedTo = 'Offline Mode (Local Storage)';
                        }
                    } else {
                        // Fall back to local storage
                        data = clients;
                        connectedTo = 'Offline Mode (Local Storage)';
                    }
                }
                
                updateRealtimeStatus('online');
                
                alert(`✅ Network sync test successful!\n\nConnected to: ${connectedTo}\nTotal clients in system: ${data.length}\n\nLatest clients:\n${data.slice(-3).map(c => `- ${c.fullName} (${c.referenceNumber})`).join('\n')}`);
                
            } catch (error) {
                updateRealtimeStatus('offline');
                const localClients = safeParseFromStorage('clients', '[]');
                alert(`⚠️ Network connection failed!\n\nError: ${error.message}\n\n📦 Current Status:\n- ${localClients.length} clients in local storage\n- Working in OFFLINE MODE\n\nNote: The app will continue working with local data. Sync will resume when connection is restored.`);
            }
        }

        async function checkConnectionStatus() {
            try {
                const startTime = Date.now();
                let response;
                let data;
                let endpoint = 'Unknown';
                let connectionStatus = '❌ Disconnected';
                
                // Try primary API
                try {
                    response = await fetch(`${API_BASE}/clients`);
                    data = await response.json();
                    endpoint = 'Primary Server';
                    connectionStatus = '✅ Connected';
                } catch (e1) {
                    // Try secondary local API if different
                    if (API_BASE_LOCAL !== API_BASE) {
                        try {
                            response = await fetch(`${API_BASE_LOCAL}/clients`);
                            data = await response.json();
                            endpoint = 'Secondary Local Server';
                            connectionStatus = '✅ Connected';
                        } catch (e2) {
                            // Fall back to local storage
                            data = clients;
                            endpoint = 'Offline Mode';
                            connectionStatus = '⚠️ Offline (Using Local Storage)';
                        }
                    } else {
                        // Fall back to local storage
                        data = clients;
                        endpoint = 'Offline Mode';
                        connectionStatus = '⚠️ Offline (Using Local Storage)';
                    }
                }
                
                const endTime = Date.now();
                const responseTime = endTime - startTime;
                
                const localData = safeParseFromStorage('clients', '[]');
                
                alert(`📡 Connection Status Report\n\n${connectionStatus}\n🌐 Endpoint: ${endpoint}\n⏱️ Response Time: ${responseTime}ms\n📊 Total Clients: ${data.length}\n💾 Local Storage: ${localData.length} records\n🔄 Auto-refresh: ${autoRefreshInterval ? 'Active (5s intervals)' : 'Inactive'}\n👤 Current User: ${currentUser ? currentUser.fullName : 'Not logged in'}`);
                
            } catch (error) {
                const localClients = safeParseFromStorage('clients', '[]');
                alert(`❌ Connection Status Report\n\n❌ API Server: Disconnected\n🌐 Primary: ${API_BASE}\n🌐 Local: ${API_BASE_LOCAL}\n⚠️ Error: ${error.message}\n\n💾 Local Storage: ${localClients.length} records available\n\nThe app will continue working with local data until connection is restored.`);
            }
        }

