        if (typeof window !== 'undefined') {
            window.openTab = openTab;
        }

        // MIS Portal Functions
        function persistMISReceiptsCache() {
            try {
                const payload = {
                    savedAt: Date.now(),
                    filters: MIS_PORTAL_STATE.filters,
                    receipts: MIS_PORTAL_STATE.receipts,
                    totals: MIS_PORTAL_STATE.totals
                };
                localStorage.setItem(MIS_RECEIPT_CACHE_KEY, JSON.stringify(payload));
            } catch (error) {
            }
        }

        function restoreMISReceiptsCache() {
            try {
                const raw = localStorage.getItem(MIS_RECEIPT_CACHE_KEY);
                if (!raw) return;
                const payload = JSON.parse(raw);
                if (!payload) return;
                if (Array.isArray(payload.receipts)) {
                    MIS_PORTAL_STATE.receipts = payload.receipts;
                }
                if (payload.totals) {
                    MIS_PORTAL_STATE.totals = Object.assign({}, MIS_PORTAL_STATE.totals, payload.totals);
                }
                if (payload.filters) {
                    MIS_PORTAL_STATE.filters = Object.assign({}, MIS_PORTAL_STATE.filters, payload.filters);
                }
                MIS_PORTAL_STATE.lastLoadedAt = payload.savedAt || 0;
            } catch (error) {
            }
        }

