        let frontDeskOrderCountInterval = null;

        // Browser Notification Support
        function requestNotificationPermission() {
            if ('Notification' in window && Notification.permission === 'default') {
                Notification.requestPermission().then(permission => {
                });
            }
        }

        function playOrderNotificationSound() {
            try {
                // Create audio context for notification sound
                const audioContext = new (window.AudioContext || window.webkitAudioContext)();
                const oscillator = audioContext.createOscillator();
                const gainNode = audioContext.createGain();
                
                oscillator.connect(gainNode);
                gainNode.connect(audioContext.destination);
                
                // Pleasant notification sound (two-tone chime)
                oscillator.frequency.setValueAtTime(800, audioContext.currentTime);
                oscillator.frequency.setValueAtTime(1000, audioContext.currentTime + 0.1);
                
                gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
                gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.3);
                
                oscillator.start(audioContext.currentTime);
                oscillator.stop(audioContext.currentTime + 0.3);
            } catch (error) {
                // Fallback: try HTML5 audio if available
                try {
                    const audio = new Audio('data:audio/wav;base64,');
                    audio.volume = 0.3;
                    audio.play().catch(() => {});
                } catch (e) {
                    // Silent fail if audio not supported
                }
            }
        }

        function showBrowserNotification(title, message, icon = '/favicon.ico', playSound = true) {
            if ('Notification' in window && Notification.permission === 'granted') {
                try {
                    const notification = new Notification(title, {
                        body: message,
                        icon: icon,
                        badge: icon,
                        tag: 'frontdesk-order',
                        requireInteraction: false
                    });
                    
                    // Play sound notification
                    if (playSound) {
                        playOrderNotificationSound();
                    }
                    
                    // Auto-close after 5 seconds
                    setTimeout(() => {
                        notification.close();
                    }, 5000);
                    
                    // Click handler to focus window
                    notification.onclick = () => {
                        window.focus();
                        notification.close();
                    };
                } catch (error) {
                }
            } else if (playSound) {
                // Play sound even if notifications are not allowed
                playOrderNotificationSound();
            }
        }

        // WebSocket Connection for Real-Time Updates
        function connectFrontDeskWebSocket() {
            // Try to get Railway gateway URL from meta tag or use default
            const metaTag = document.querySelector('meta[name="rt-base"]');
            const rtBase = metaTag?.content?.trim() || '';
            const wsUrl = rtBase 
                ? rtBase.replace(/^https?:\/\//, 'wss://').replace(/\/$/, '') + '/ws'
                : 'wss://` + window.location.host + `/ws';
            
            if (frontDeskWebSocket && frontDeskWebSocket.readyState === WebSocket.OPEN) {
                return; // Already connected
            }

            try {
                frontDeskWebSocket = new WebSocket(wsUrl);

                frontDeskWebSocket.onopen = () => {
                    // Subscribe to orders channel
                    frontDeskWebSocket.send(JSON.stringify({
                        type: 'subscribe',
                        channels: ['orders', 'clients', 'visitors']
                    }));
                    updateFrontDeskConnectionStatus(true);
                };

                frontDeskWebSocket.onmessage = (event) => {
                    try {
                        const data = JSON.parse(event.data);
                        
                        if (data.type === 'event') {
                            handleFrontDeskRealtimeEvent(data);
                        } else if (data.type === 'subscribed') {
                        }
                    } catch (error) {
                    }
                };

                frontDeskWebSocket.onerror = (error) => {
                    console.error('❌ Front Desk WebSocket error:', error);
                    updateFrontDeskConnectionStatus(false);
                };

                frontDeskWebSocket.onclose = () => {
                    updateFrontDeskConnectionStatus(false);
                    setTimeout(connectFrontDeskWebSocket, 5000);
                };
            } catch (error) {
                console.error('Failed to connect Front Desk WebSocket:', error);
                updateFrontDeskConnectionStatus(false);
            }
        }

        function handleFrontDeskRealtimeEvent(data) {
            const { resource, action, data: eventData } = data;
            
            if (resource === 'orders') {
                if (action === 'created') {
                    refreshAllFrontDeskOrderTabs();
                    updatePendingOrderCount();
                    showBrowserNotification(
                        '🆕 New Order Received',
                        `Order #${eventData?.order_number || eventData?.id || 'N/A'} from ${eventData?.customer_name || 'Customer'}`,
                        '/favicon.ico',
                        true // Play sound
                    );
                    // Show visual indicator
                    showNewOrderIndicator();
                } else if (action === 'updated') {
                    refreshAllFrontDeskOrderTabs();
                    updatePendingOrderCount();
                    // Show notification for status changes (no sound for updates)
                    if (eventData?.status) {
                        showBrowserNotification(
                            '📦 Order Status Updated',
                            `Order #${eventData?.order_number || eventData?.id || 'N/A'} is now ${eventData.status}`,
                            '/favicon.ico',
                            false // No sound for updates
                        );
                    }
                }
            } else if (resource === 'clients') {
                if (action === 'created' || action === 'updated') {
                    // Refresh client lookup if tab is open
                    const clientLookupTab = document.getElementById('frontdeskClientLookup');
                    if (clientLookupTab && !clientLookupTab.classList.contains('hidden')) {
                        if (typeof performClientLookup === 'function') {
                            // Optionally refresh client lookup
                        }
                    }
                }
            } else if (resource === 'visitors') {
                if (action === 'created') {
                    refreshVisitors();
                    showBrowserNotification(
                        '🚪 New Visitor',
                        `${eventData?.name || 'Visitor'} - ${eventData?.purpose || 'Visit'}`,
                        '/favicon.ico',
                        false // No sound for visitors
                    );
                }
            }
        }

        function refreshAllFrontDeskOrderTabs() {
            // Refresh all order tabs
            if (typeof refreshPendingOrders === 'function') refreshPendingOrders();
            if (typeof refreshProcessingOrders === 'function') refreshProcessingOrders();
            if (typeof refreshShippedOrders === 'function') refreshShippedOrders();
            if (typeof refreshDeliveredOrders === 'function') refreshDeliveredOrders();
            if (typeof refreshAllOrders === 'function') refreshAllOrders();
            // Update order count after refresh
            setTimeout(updatePendingOrderCount, 500);
        }

        async function updatePendingOrderCount() {
            try {
                // Get pending orders count from API or localStorage
                let pendingCount = 0;
                
                // Try API first
                try {
                    const response = await fetch('/api/orders?status=pending');
                    if (response.ok) {
                        const orders = await response.json();
                        pendingCount = Array.isArray(orders) ? orders.length : 0;
                    }
                } catch (error) {
                }
                
                // Fallback to localStorage
                if (pendingCount === 0) {
                    try {
                        const localOrders = JSON.parse(localStorage.getItem('dyna_online_orders') || '[]');
                        pendingCount = Array.isArray(localOrders) 
                            ? localOrders.filter(o => (o.status || '').toLowerCase() === 'pending').length 
                            : 0;
                    } catch (error) {
                    }
                }
                
                frontDeskPendingOrderCount = pendingCount;
                updateOrderCountBadge(pendingCount);
            } catch (error) {
            }
        }

        function updateOrderCountBadge(count) {
            // Update tab title with order count
            const frontDeskTab = document.querySelector('[onclick*="openTab(\'frontdesk\'"]') || 
                               document.querySelector('[onclick*="openTab(\"frontdesk\""]');
            
            if (frontDeskTab) {
                const baseText = 'Front Desk Portal';
                if (count > 0) {
                    frontDeskTab.textContent = `${baseText} (${count})`;
                    frontDeskTab.style.position = 'relative';
                    
                    // Add/update badge
                    let badge = frontDeskTab.querySelector('.order-count-badge');
                    if (!badge) {
                        badge = document.createElement('span');
                        badge.className = 'order-count-badge';
                        badge.style.cssText = 'position:absolute; top:-8px; right:-8px; background:#ef4444; color:white; border-radius:50%; width:20px; height:20px; display:flex; align-items:center; justify-content:center; font-size:0.7rem; font-weight:bold; border:2px solid white;';
                        frontDeskTab.appendChild(badge);
                    }
                    badge.textContent = count > 99 ? '99+' : count;
                    badge.style.display = 'flex';
                } else {
                    frontDeskTab.textContent = baseText;
                    const badge = frontDeskTab.querySelector('.order-count-badge');
                    if (badge) {
                        badge.style.display = 'none';
                    }
                }
            }
            
            // Also update document title
            const baseTitle = document.title.replace(/\(\d+\)\s*$/, '').trim();
            if (count > 0) {
                document.title = `(${count}) ${baseTitle}`;
            } else {
                document.title = baseTitle;
            }
        }

        function showNewOrderIndicator() {
            // Add visual indicator to pending orders tab
            const pendingTab = document.querySelector('[onclick="showOrderTab(\'pending\')"]');
            if (pendingTab) {
                pendingTab.style.position = 'relative';
                let indicator = pendingTab.querySelector('.new-order-indicator');
                if (!indicator) {
                    indicator = document.createElement('span');
                    indicator.className = 'new-order-indicator';
                    indicator.style.cssText = 'position:absolute; top:-5px; right:-5px; width:12px; height:12px; background:#ef4444; border-radius:50%; border:2px solid white; animation:pulse 2s infinite;';
                    pendingTab.appendChild(indicator);
                }
                // Remove indicator after 10 seconds
                setTimeout(() => {
                    if (indicator && indicator.parentNode) {
                        indicator.remove();
                    }
                }, 10000);
            }
        }

        function updateFrontDeskConnectionStatus(connected) {
            // Add connection status indicator
            let statusIndicator = document.getElementById('frontdeskRealtimeStatus');
            if (!statusIndicator) {
                statusIndicator = document.createElement('div');
                statusIndicator.id = 'frontdeskRealtimeStatus';
                statusIndicator.style.cssText = 'position:fixed; bottom:20px; right:20px; padding:8px 12px; border-radius:8px; font-size:0.75rem; z-index:10000; box-shadow:0 2px 8px rgba(0,0,0,0.15);';
                document.body.appendChild(statusIndicator);
            }
            
            if (connected) {
                statusIndicator.textContent = '🟢 Real-time Connected';
                statusIndicator.style.background = '#10b981';
                statusIndicator.style.color = 'white';
            } else {
                statusIndicator.textContent = '🔴 Real-time Disconnected';
                statusIndicator.style.background = '#ef4444';
                statusIndicator.style.color = 'white';
            }
        }

        function initializeFrontDeskRealtime() {
            if (frontDeskRealtimeInitialized) return;
            frontDeskRealtimeInitialized = true;

            // Request notification permission
            requestNotificationPermission();

            // Connect to WebSocket
            connectFrontDeskWebSocket();

            // Initial order count update
            updatePendingOrderCount();

            // Set up order count refresh (every 60 seconds)
            if (frontDeskOrderCountInterval) {
                clearInterval(frontDeskOrderCountInterval);
            }
            frontDeskOrderCountInterval = setInterval(() => {
                updatePendingOrderCount();
            }, 60000);

            // Set up auto-refresh fallback (every 30 seconds)
            if (frontDeskAutoRefreshInterval) {
                clearInterval(frontDeskAutoRefreshInterval);
            }
            frontDeskAutoRefreshInterval = setInterval(() => {
                // Only refresh if WebSocket is not connected
                if (!frontDeskWebSocket || frontDeskWebSocket.readyState !== WebSocket.OPEN) {
                    refreshAllFrontDeskOrderTabs();
                }
            }, 30000);

            // Listen to custom events (for local updates)
            window.addEventListener('orders:created', () => {
                refreshAllFrontDeskOrderTabs();
                showBrowserNotification('🆕 New Order', 'A new order has been created', '/favicon.ico', true);
            });

            window.addEventListener('orders:updated', () => {
                refreshAllFrontDeskOrderTabs();
            });

        }

        // Make functions globally accessible
        window.refreshAllFrontDeskOrderTabs = refreshAllFrontDeskOrderTabs;
        window.initializeFrontDeskRealtime = initializeFrontDeskRealtime;

        function loadMISBranches() {
            const branchSelect = document.getElementById('misBranchSelect');
            if (!branchSelect) return;

            const current = MIS_PORTAL_STATE.filters.branch || 'all';

            branchSelect.innerHTML = '<option value="all">All Branches</option>';

            (Array.isArray(branches) ? branches : []).forEach(branch => {
                if (!branch) return;
                const option = document.createElement('option');
                option.value = branch.id;
                option.textContent = branch.name;
                branchSelect.appendChild(option);
            });

            const selectedOption = branchSelect.querySelector(`option[value="${escapeForSelector(current)}"]`);
            branchSelect.value = selectedOption ? current : 'all';
        }

        function summarizeMISReceipts(receipts) {
            const summary = {
                count: Array.isArray(receipts) ? receipts.length : 0,
                totalAmount: 0,
                branchBreakdown: []
            };
            if (!Array.isArray(receipts) || !receipts.length) return summary;
            const breakdown = new Map();
            receipts.forEach(receipt => {
                if (!receipt) return;
                const amount = Number(receipt.totalAmount ?? receipt.total ?? 0);
                if (Number.isFinite(amount)) {
                    summary.totalAmount += amount;
                }
                const branchKey = receipt.branch || receipt.branchId || receipt.clientInfo?.branch || 'Unknown';
                if (!breakdown.has(branchKey)) {
                    breakdown.set(branchKey, { branch: branchKey, count: 0, total: 0 });
                }
                const entry = breakdown.get(branchKey);
                entry.count += 1;
                if (Number.isFinite(amount)) {
                    entry.total += amount;
                }
            });
            summary.branchBreakdown = Array.from(breakdown.values()).sort((a, b) => a.branch.localeCompare(b.branch));
            return summary;
        }

        function matchesMISSearch(receipt, term) {
            if (!term) return true;
            const haystack = [
                receipt.clientName,
                receipt.customerName,
                receipt.customerPhone,
                receipt.customerEmail,
                receipt.saleNumber,
                receipt.receiptNumber,
                receipt.id,
                receipt.consultant,
                receipt.soldBy,
                receipt.metadata?.consultant,
                receipt.metadata?.soldBy
            ]
                .concat(
                    Array.isArray(receipt.products)
                        ? receipt.products.map((p) => p?.name || p?.productName || '')
                        : []
                )
                .filter(Boolean)
                .join(' ')
                .toLowerCase();
            return haystack.includes(term.toLowerCase());
        }

        function normalizeOfflineReceipt(record) {
            if (!record) return null;
            const total = Number(record.totalAmount ?? record.total ?? 0);
            const timestamp =
                record.timestamp ||
                record.saleDate ||
                (record.createdAt ? new Date(record.createdAt).toISOString() : new Date().toISOString());
            return {
                id: record.id || record.saleNumber || `OFF-${Date.now()}`,
                saleNumber: record.saleNumber || record.id,
                receiptNumber: record.saleNumber || record.id,
                branch: record.branch || record.branchId || record.clientInfo?.branch || 'Unknown',
                branchId: record.branch || record.branchId || null,
                clientName: record.customerName || record.clientName || record.clientInfo?.fullName || '',
                customerName: record.customerName || record.clientName || record.clientInfo?.fullName || '',
                customerPhone: record.phone || record.customerPhone || record.clientInfo?.phone || '',
                customerEmail: record.email || record.customerEmail || record.clientInfo?.email || '',
                customerType: record.customerType || record.clientInfo?.type || 'customer',
                paymentMethod: record.paymentMethod || 'cash',
                total,
                totalAmount: total,
                totalBV: Number(record.totalBV || 0),
                products: Array.isArray(record.products) ? record.products : [],
                medicines: Array.isArray(record.medicines) ? record.medicines : [],
                items: Array.isArray(record.items) ? record.items : [],
                timestamp
            };
        }

        function applyMISSearchFilter(list) {
            const term = MIS_PORTAL_STATE.filters.search?.trim().toLowerCase() || '';
            if (!term) return list;
            return list.filter((receipt) => matchesMISSearch(receipt, term));
        }

        function getReceiptTimestamp(receipt) {
            if (!receipt) return null;
            const candidates = [
                receipt.timestamp,
                receipt.saleDate,
                receipt.sale_date,
                receipt.createdAt,
                receipt.created_at
            ];
            for (const value of candidates) {
                if (!value) continue;
                const date = new Date(value);
                if (!Number.isNaN(date.getTime())) {
                    return date;
                }
            }
            return null;
        }

        function sumReceiptsForWindow(receipts, windowFn, selector) {
            if (!Array.isArray(receipts) || typeof windowFn !== 'function') return 0;
            return receipts.reduce((sum, receipt) => {
                const timestamp = getReceiptTimestamp(receipt);
                if (!timestamp || !windowFn(timestamp)) return sum;
                const value = selector ? selector(receipt) : receipt.totalAmount || receipt.total || 0;
                const numeric = Number(value);
                return Number.isFinite(numeric) ? sum + numeric : sum;
            }, 0);
        }

        function countReceiptsForWindow(receipts, windowFn) {
            if (!Array.isArray(receipts) || typeof windowFn !== 'function') return 0;
            return receipts.reduce((count, receipt) => {
                const timestamp = getReceiptTimestamp(receipt);
                if (!timestamp || !windowFn(timestamp)) return count;
                return count + 1;
            }, 0);
        }

        async function loadMISReceipts({ force = false } = {}) {
            ensureMISPortalInitialized();
            const now = Date.now();
            if (
                !force &&
                MIS_PORTAL_STATE.receipts.length &&
                now - MIS_PORTAL_STATE.lastLoadedAt < MIS_RECEIPT_CACHE_EXPIRY_MS
            ) {
                renderMISReceipts();
                return MIS_PORTAL_STATE.receipts;
            }

            MIS_PORTAL_STATE.loading = true;
            const { branch, from, to } = MIS_PORTAL_STATE.filters;
            const params = new URLSearchParams();
            if (branch && branch !== 'all') params.set('branch', branch);
            if (from) {
                const fromDate = new Date(from);
                if (!Number.isNaN(fromDate.getTime())) params.set('start', fromDate.toISOString());
            }
            if (to) {
                const toDate = new Date(to);
                if (!Number.isNaN(toDate.getTime())) params.set('end', toDate.toISOString());
            }

            let response = null;
            try {
                const endpoint = params.toString() ? `/mis/receipts?${params}` : '/mis/receipts';
                response = await apiRequest(endpoint);
            } catch (error) {
            }

            let receipts = extractArray(response?.receipts, []);
            if (!receipts.length) {
                const offline = safeParseFromStorage('branch_walkin_sales', '[]');
                if (Array.isArray(offline) && offline.length) {
                    receipts = offline.map(normalizeOfflineReceipt).filter(Boolean);
                }
            }
            MIS_PORTAL_STATE.receipts = receipts;
            const responseTotals = response?.totals;
            if (responseTotals) {
                MIS_PORTAL_STATE.totals = {
                    count: Number.isFinite(Number(responseTotals.count))
                        ? Number(responseTotals.count)
                        : receipts.length,
                    totalAmount: Number(responseTotals.totalAmount || responseTotals.total || 0) || 0,
                    branchBreakdown: Array.isArray(responseTotals.branchBreakdown)
                        ? responseTotals.branchBreakdown
                        : summarizeMISReceipts(receipts).branchBreakdown
                };
            } else {
                MIS_PORTAL_STATE.totals = summarizeMISReceipts(receipts);
            }
            MIS_PORTAL_STATE.lastLoadedAt = Date.now();
            persistMISReceiptsCache();
            MIS_PORTAL_STATE.loading = false;
            renderMISReceipts();
            return receipts;
        }

        function renderMISReceipts() {
            const filtered = applyMISSearchFilter(MIS_PORTAL_STATE.receipts || []);
            displayMISReportsTable(filtered);
            updateMISSummary(filtered);
            renderMISAnalytics(filtered);
        }

        function renderMISAnalytics(receiptsList) {
            ensureMISPortalInitialized();
            const list = Array.isArray(receiptsList)
                ? receiptsList
                : applyMISSearchFilter(MIS_PORTAL_STATE.receipts || []);
            const select = document.getElementById('misComparisonPeriod');
            const mode = select ? select.value : 'none';
            const summary = applyMISComparisons(mode, list);
            renderMISComparisonAlerts(summary);
            renderMISTrendChart(summary, list);
        }

        function applyMISComparisons(mode, receipts) {
            if (!Array.isArray(receipts)) {
                return { mode: 'none', label: null, items: [] };
            }
            if (!mode || mode === 'none') {
                return { mode: 'none', label: null, items: [] };
            }
            const windowFn = buildComparisonWindow(mode);
            if (typeof windowFn !== 'function') {
                return { mode: 'none', label: null, items: [] };
            }
            const label = FINANCE_COMPARISON_LABELS[mode] || 'previous period';
            const todayKey = new Date().toISOString().slice(0, 10);
            const todayReceipts = receipts.filter((receipt) => extractFinanceDateKey(receipt) === todayKey);
            const currentAmount = todayReceipts.reduce(
                (sum, receipt) =>
                    sum + Number(receipt.totalAmount ?? receipt.total ?? receipt.subtotal ?? 0),
                0
            );
            const currentCount = todayReceipts.length;
            const baselineAmount = sumReceiptsForWindow(receipts, windowFn, (receipt) =>
                Number(receipt.totalAmount ?? receipt.total ?? receipt.subtotal ?? 0)
            );
            const baselineCount = countReceiptsForWindow(receipts, windowFn);

            const amountSummary = buildComparisonData(currentAmount, baselineAmount, label, 'totalAmount');
            amountSummary.metricName = MIS_METRIC_NAMES.totalAmount;
            amountSummary.mode = mode;

            const countSummary = buildComparisonData(currentCount, baselineCount, label, 'receiptCount');
            countSummary.metricName = MIS_METRIC_NAMES.receiptCount;
            countSummary.mode = mode;

            return {
                mode,
                label,
                items: [amountSummary, countSummary],
                metrics: {
                    totalAmount: currentAmount,
                    receiptCount: currentCount
                }
            };
        }

        function renderMISComparisonAlerts(summary) {
            const container = document.getElementById('misComparisonAlerts');
            if (!container) return;
            if (!summary || summary.mode === 'none') {
                container.innerHTML =
                    '<div style="padding:10px; border:1px dashed #cbd5f5; border-radius:8px; background:#f8fafc; color:#475569;">Select a comparison period to see MIS performance trends.</div>';
                return;
            }
            const items = Array.isArray(summary.items) ? summary.items : [];
            if (!items.length) {
                container.innerHTML =
                    '<div style="padding:10px; border:1px solid #e2e8f0; border-radius:8px; background:#f1f5f9; color:#475569;">No receipts recorded for today yet.</div>';
                return;
            }

            const alerts = items
                .map((item) => {
                    if (!item || !item.text) return null;
                    if (item.direction === 'down' && Math.abs(item.deltaPercent || 0) >= MIS_ALERT_THRESHOLD) {
                        dispatchMISAlert(item);
                    }
                    const color = item.color || '#475569';
                    const badgeColor = item.direction === 'down' ? '#dc2626' : item.direction === 'up' ? '#16a34a' : '#475569';
                    const icon = item.direction === 'down' ? '⬇️' : item.direction === 'up' ? '⬆️' : '⏺️';
                    const metricName = item.metricName || MIS_METRIC_NAMES[item.key] || item.key || 'Metric';
                    const deltaValue = formatCurrencyNAD(item.diff || 0);
                    const card = `
                        <div style="display:flex; align-items:flex-start; gap:10px; padding:10px 12px; border:1px solid #e2e8f0; border-radius:10px; background:#ffffff;">
                            <div style="font-size:1.25rem;">${icon}</div>
                            <div style="flex:1;">
                                <div style="font-weight:600; color:${color};">${escapeHtml(metricName)} ${escapeHtml(item.text || '')}</div>
                                <div style="font-size:0.85rem; color:#475569;">Δ ${deltaValue} (previous ${formatCurrencyNAD(item.previous || 0)})</div>
                            </div>
                            <span style="padding:4px 10px; border-radius:999px; background:${badgeColor}20; color:${badgeColor}; font-size:0.75rem; font-weight:600;">
                                ${item.direction === 'down' ? 'Attention' : item.direction === 'up' ? 'Growth' : 'Stable'}
                            </span>
                        </div>
                    `;
                    return card;
                })
                .filter(Boolean)
                .join('');

            container.innerHTML =
                alerts ||
                `<div style="padding:10px; border:1px solid #e2e8f0; border-radius:8px; background:#f1f5f9; color:#475569;">No significant changes vs ${escapeHtml(summary.label || 'previous period')}.</div>`;
        }

        function dispatchMISAlert(summary) {
            if (!summary || summary.direction !== 'down') return;
            const percent = Math.abs(summary.deltaPercent || 0);
            if (percent < MIS_ALERT_THRESHOLD) return;
            const key = `${summary.key || 'metric'}:${summary.mode || 'none'}`;
            const last = MIS_ALERT_STATE.recent.get(key) || 0;
            const now = Date.now();
            if (now - last < MIS_ALERT_THROTTLE_MS) return;
            MIS_ALERT_STATE.recent.set(key, now);
            const metricName = summary.metricName || MIS_METRIC_NAMES[summary.key] || summary.key;
            const percentText = formatPercentValue(summary.deltaPercent || 0);
            const message = `${metricName} down ${percentText}% vs ${summary.label || 'previous period'}`;
            try {
                recordDepartmentEvent &&
                    recordDepartmentEvent('mis_alert', {
                        metric: summary.key,
                        metricName,
                        dropPercent: summary.deltaPercent,
                        dropValue: summary.diff,
                        comparison: summary.label,
                        currentValue: summary.current,
                        previousValue: summary.previous,
                        triggeredAt: new Date().toISOString()
                    });
            } catch (error) {
            }
            try {
                logSyncEvent && logSyncEvent('mis-alert', message, { severity: 'warning', scope: 'mis' });
            } catch (_) {}
        }

        function aggregateReceiptsByDate(records) {
            const map = new Map();
            if (!Array.isArray(records)) return map;
            records.forEach((receipt) => {
                const key = extractFinanceDateKey(receipt);
                if (!key) return;
                const amount = Number(receipt.totalAmount ?? receipt.total ?? receipt.subtotal ?? 0);
                if (!Number.isFinite(amount)) return;
                map.set(key, (map.get(key) || 0) + amount);
            });
            return map;
        }

        function renderMISTrendChart(summary, receipts) {
            const container = document.getElementById('misTrendChart');
            if (!container) return;
            if (!Array.isArray(receipts) || receipts.length === 0) {
                container.innerHTML =
                    '<div style="padding:10px; border:1px solid #e2e8f0; border-radius:8px; background:#f8fafc; color:#475569;">No receipts available to chart yet.</div>';
                return;
            }
            const comparisonLabel =
                summary && summary.mode !== 'none'
                    ? `Comparison: ${summary.label || 'previous period'}`
                    : '14-day sales trend';

            const days = [];
            const today = new Date();
            for (let offset = 13; offset >= 0; offset -= 1) {
                const date = new Date(today.getFullYear(), today.getMonth(), today.getDate());
                date.setDate(date.getDate() - offset);
                const key = date.toISOString().slice(0, 10);
                const label = date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
                days.push({ key, label });
            }

            const totalsByDate = aggregateReceiptsByDate(receipts);
            const totals = days.map(({ key, label }) => ({
                key,
                label,
                amount: totalsByDate.get(key) || 0
            }));

            const values = totals.map((item) => item.amount);
            const maxValue = values.length ? Math.max(...values, 0) : 0;
            const minValue = values.length ? Math.min(...values, 0) : 0;
            const range = Math.max(maxValue - minValue, 1);
            const points = totals
                .map((item, index) => {
                    const x = totals.length > 1 ? (index / (totals.length - 1)) * 100 : 0;
                    const y = 100 - ((item.amount - minValue) / range) * 100;
                    return `${x.toFixed(2)},${y.toFixed(2)}`;
                })
                .join(' ');
            const zeroY = 100 - ((0 - minValue) / range) * 100;
            const latest = totals[totals.length - 1] || { amount: 0 };
            const earliest = totals[0] || { amount: 0 };
            const delta = latest.amount - earliest.amount;
            const deltaColor = delta >= 0 ? '#16a34a' : '#dc2626';
            const deltaText = `${delta >= 0 ? '▲' : '▼'} ${formatCurrencyNAD(Math.abs(delta))}`;

            const labels = totals
                .map((item, index) => {
                    if (index === 0 || index === totals.length - 1 || index === Math.floor(totals.length / 2)) {
                        const align =
                            index === 0 ? 'left' : index === totals.length - 1 ? 'right' : 'center';
                        return `<div style="flex:1; text-align:${align}; font-size:0.75rem; color:#64748b;">${escapeHtml(item.label)}</div>`;
                    }
                    return '<div style="flex:1;"></div>';
                })
                .join('');

            container.innerHTML = `
                <div style="border:1px solid #e2e8f0; border-radius:12px; padding:16px; background:#ffffff;">
                    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-bottom:12px;">
                        <div style="font-weight:600; color:#1e293b;">14-Day Sales Trend</div>
                        <div style="font-size:0.85rem; color:#475569;">${escapeHtml(comparisonLabel)}</div>
                        <div style="font-size:0.85rem; color:${deltaColor}; font-weight:600;">${deltaText} vs first day</div>
                    </div>
                    <svg viewBox="0 0 100 100" preserveAspectRatio="none" style="width:100%; height:160px; background:linear-gradient(180deg,#f8fafc,#ffffff); border-radius:8px;">
                        <polyline points="${points}" fill="none" stroke="#0ea5e9" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"></polyline>
                        <polygon points="${points} 100,100 0,100" fill="rgba(14,165,233,0.12)"></polygon>
                        <line x1="0" y1="${zeroY}" x2="100" y2="${zeroY}" stroke="#e2e8f0" stroke-dasharray="4,4"></line>
                    </svg>
                    <div style="display:flex; margin-top:6px;">${labels}</div>
                </div>
            `;
        }
        function filterMISReports() {
            ensureMISPortalInitialized();
            const branchId = document.getElementById('misBranchSelect')?.value || 'all';
            const searchTerm = document.getElementById('misSearchInput')?.value?.trim() || '';
            const fromInput = document.getElementById('misDateFrom')?.value || '';
            const toInput = document.getElementById('misDateTo')?.value || '';

            const filters = MIS_PORTAL_STATE.filters;
            const branchChanged = branchId !== filters.branch;
            const fromChanged = fromInput !== (filters.from || '');
            const toChanged = toInput !== (filters.to || '');
            const searchChanged = searchTerm !== (filters.search || '');

            filters.branch = branchId;
            filters.search = searchTerm;
            filters.from = fromInput || null;
            filters.to = toInput || null;

            persistMISReceiptsCache();

            if (branchChanged || fromChanged || toChanged || MIS_PORTAL_STATE.receipts.length === 0) {
                loadMISReceipts({ force: true });
            } else if (searchChanged) {
                renderMISReceipts();
            } else {
                renderMISReceipts();
            }
        }

        function displayMISReports() {
            // Default to today's receipts if no date range selected
            const fromInput = document.getElementById('misDateFrom');
            const toInput = document.getElementById('misDateTo');
            if (fromInput && toInput && !fromInput.value && !toInput.value) {
                setMISDateToday();
            } else {
                filterMISReports();
            }
        }

        function displayMISReportsTable(reportsToDisplay) {
            const displayDiv = document.getElementById('misReportsDisplay');
            if (!displayDiv) return;
            
            if (reportsToDisplay.length === 0) {
                displayDiv.innerHTML = '<p style="text-align: center; color: #7f8c8d;">No sales receipts found.</p>';
                return;
            }
            
            let html = `
                <table style="width: 100%; border-collapse: collapse;">
                    <thead>
                        <tr style="background: #c41e3a; color: white;">
                            <th style="padding: 12px; text-align: left; border: 1px solid #ddd;">Invoice No.</th>
                            <th style="padding: 12px; text-align: left; border: 1px solid #ddd;">Client</th>
                            <th style="padding: 12px; text-align: left; border: 1px solid #ddd;">Items Purchased</th>
                            <th style="padding: 12px; text-align: left; border: 1px solid #ddd;">Time</th>
                            <th style="padding: 12px; text-align: left; border: 1px solid #ddd;">Dispenser</th>
                            <th style="padding: 12px; text-align: left; border: 1px solid #ddd;">Total</th>
                        </tr>
                    </thead>
                    <tbody>
            `;
            
            reportsToDisplay.forEach((report, index) => {
                const dt = report.timestamp ? new Date(report.timestamp) : null;
                const date = dt ? dt.toLocaleDateString('en-GB') : '—';
                const time = dt ? dt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—';
                const totalAmount = calculateReportTotal(report);
                const itemsPurchased = getItemsPurchased(report).join('; ');
                const dispenser = getReportDispenser(report) || '—';
                
                const rowColor = index % 2 === 0 ? '#f8f9fa' : 'white';
                
                html += `
                    <tr style="background: ${rowColor};">
                        <td style="padding: 10px; border: 1px solid #ddd;">${report.id}</td>
                        <td style="padding: 10px; border: 1px solid #ddd;">${report.clientInfo?.fullName || 'N/A'}</td>
                        <td style="padding: 10px; border: 1px solid #ddd;">${itemsPurchased || '—'}</td>
                        <td style="padding: 10px; border: 1px solid #ddd;">${time}</td>
                        <td style="padding: 10px; border: 1px solid #ddd;">${dispenser}</td>
                        <td style="padding: 10px; border: 1px solid #ddd; font-weight: bold;">N$${totalAmount.toFixed(2)}</td>
                    </tr>
                `;
            });
            
            html += `
                    </tbody>
                </table>
            `;
            
            displayDiv.innerHTML = html;
        }

        function getItemsPurchased(report) {
            if (!report) return [];
            if (Array.isArray(report.items) && report.items.length > 0) {
                return report.items
                    .map((item) => item.productName || item.name || item.product || item.description || '')
                    .filter(Boolean);
            }
            if (Array.isArray(report.products) && report.products.length > 0) {
                return report.products
                    .map((p) => p.name || p.product || p.description || p.productName || '')
                    .filter(Boolean);
            }
            if (Array.isArray(report.medicines) && report.medicines.length > 0) {
                return report.medicines.map((m) => m.name || m.product || m.description || '').filter(Boolean);
            }
            return [];
        }

        function getReportDispenser(report) {
            // Prefer dispenser from any dispensed medicine
            if (Array.isArray(report.medicines)) {
                const dispensed = report.medicines.find(m => m.dispensedBy);
                if (dispensed && dispensed.dispensedBy) return dispensed.dispensedBy;
                const paidBy = report.medicines.find(m => m.paidBy);
                if (paidBy && paidBy.paidBy) return paidBy.paidBy;
            }
            // Fallbacks: consultant or explicit cashier fields if present
            return (
                report.soldBy ||
                report.dispensedBy ||
                report.cashier ||
                report.consultant ||
                report.metadata?.soldBy ||
                null
            );
        }

        function setMISDateToday() {
            const fromInput = document.getElementById('misDateFrom');
            const toInput = document.getElementById('misDateTo');
            const now = new Date();
            const start = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0);
            const end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59);
            const toLocal = (d) => {
                const pad = (n) => String(n).padStart(2, '0');
                return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
            };
            if (fromInput) fromInput.value = toLocal(start);
            if (toInput) toInput.value = toLocal(end);
            filterMISReports();
        }

        function clearMISDateFilters() {
            const fromInput = document.getElementById('misDateFrom');
            const toInput = document.getElementById('misDateTo');
            if (fromInput) fromInput.value = '';
            if (toInput) toInput.value = '';
            filterMISReports();
        }

        function calculateReportTotal(report) {
            if (!report) return 0;
            const directValues = [
                report.totalAmount,
                report.total,
                report.summary?.total,
                report.data?.total,
                report.subtotal
            ]
                .map((value) => Number(value))
                .filter((value) => Number.isFinite(value) && value !== 0);
            if (directValues.length) {
                return directValues[0];
            }

            const lineItems = []
                .concat(Array.isArray(report.products) ? report.products : [])
                .concat(Array.isArray(report.items) ? report.items : [])
                .concat(Array.isArray(report.medicines) ? report.medicines : []);
            if (lineItems.length) {
                const lineTotal = lineItems.reduce((sum, item) => {
                    const quantity = Number(item.quantity || 1);
                    const price =
                        Number(item.amount) ||
                        Number(item.total) ||
                        Number(item.totalAmount) ||
                        Number(item.cp) ||
                        Number(item.price) ||
                        Number(
                            (item.currentPrice && (item.currentPrice.cp || item.currentPrice.price)) ||
                                item.unitPrice ||
                                0
                        );
                    if (!Number.isFinite(quantity) || !Number.isFinite(price)) return sum;
                    if (item.currentPrice && item.currentPrice.cp) {
                        return sum + Number(item.currentPrice.cp) * quantity;
                    }
                    return sum + price * (item.amount ? 1 : quantity);
                }, 0);
                if (Number.isFinite(lineTotal) && lineTotal > 0) {
                    return lineTotal;
                }
            }

            if (Array.isArray(report.medicines) && report.medicines.length) {
                try {
                    let membership = report.clientInfo?.membershipStatus;
                    if (!membership && Array.isArray(clients)) {
                        const clientRef =
                            report.clientId ||
                            report.clientInfo?.referenceNumber ||
                            report.clientInfo?.nbNumber;
                        const client = clients.find((c) => c.referenceNumber === clientRef);
                        membership = client?.membershipStatus;
                    }
                    if (membership === 'member' || membership === 'referred') {
                        const totals = calculatePrescriptionTotals(report.medicines, membership);
                        return membership === 'member'
                            ? Number(totals.total?.dp || 0)
                            : Number(totals.total?.cp || 0);
                    }
                } catch (error) {
                }
            }

            return 0;
        }

        function updateMISSummary(reportsToDisplay) {
            const totalCount = document.getElementById('misTotalCount');
            const branchSummary = document.getElementById('misBranchSummary');
            const stockSummary = document.getElementById('misStockSummary');
            
            if (totalCount) {
                totalCount.textContent = `Total Records: ${reportsToDisplay.length}`;
            }
            
            if (branchSummary) {
                const byBranch = {};
                reportsToDisplay.forEach(r => {
                    const key = r.branch || r.clientInfo?.branch || 'Unknown';
                    byBranch[key] = (byBranch[key] || 0) + 1;
                });
                const parts = Object.entries(byBranch).map(([k, v]) => `${k}: ${v}`);
                branchSummary.textContent = parts.length ? `By Branch: ${parts.join(' | ')}` : `Showing ${reportsToDisplay.length} receipt(s)`;
            }

            // Stock summary (company-wide quick view)
            if (stockSummary) {
                try {
                    const inv = JSON.parse(localStorage.getItem('dynapharm_inventory') || '{}');
                    const totals = Object.keys(inv).reduce((acc, k) => {
                        const q = parseFloat(inv[k]?.currentStock || 0);
                        const ro = inv[k]?.reorderLevel ?? 5;
                        acc.qty += q;
                        if (q <= ro) acc.low += 1;
                        return acc;
                    }, { qty: 0, low: 0 });
                    stockSummary.textContent = `Stock: Qty ${totals.qty} | Low ${totals.low}`;
                } catch (e) {
                    stockSummary.textContent = 'Stock: N/A';
                }
            }

            renderMISBranchDailySummary(reportsToDisplay);

            // Render inventory breakdown table (uses consolidated inventory for now)
            try {
                const branchId = document.getElementById('misBranchSelect')?.value || 'all';
                renderInventoryBreakdown('misInventoryBreakdown', branchId);
            } catch (e) {}
        }

        async function refreshMISData() {
            ensureMISPortalInitialized();
            try {
                await loadData();
            } catch (error) {
            }
            try {
                await loadMISReceipts({ force: true });
                alert('MIS data refreshed successfully!');
            } catch (error) {
                console.error('refreshMISData error', error);
                alert('Unable to refresh MIS data. Showing cached results.');
                renderMISReceipts();
            }
            try {
                const branchId = document.getElementById('misBranchSelect')?.value || 'all';
                renderInventoryBreakdown('misInventoryBreakdown', branchId);
            } catch (e) {
            }
        }

        function exportMISData() {
            ensureMISPortalInitialized();
            const list = applyMISSearchFilter(MIS_PORTAL_STATE.receipts || []);
            if (!list.length) {
                alert('No MIS receipts available to export for the current filters.');
                return;
            }
            const csv = convertMISReceiptsToCSV(list);
            const blob = new Blob([csv], { type: 'text/csv' });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `MIS_Sales_Receipts_${new Date().toISOString().split('T')[0]}.csv`;
            a.click();
        }

        function convertMISReceiptsToCSV(receiptsData) {
            const header = [
                'Receipt ID',
                'Sale Date',
                'Client Name',
                'NB Number',
                'Phone',
                'Email',
                'Sold By',
                'Payment Method',
                'Total Amount',
                'Products'
            ];
            const rows = [header.join(',')];
            (Array.isArray(receiptsData) ? receiptsData : []).forEach((receipt) => {
                const date = receipt.timestamp ? new Date(receipt.timestamp).toLocaleString() : '';
                const totalAmount = calculateReportTotal(receipt);
                const nbNumber =
                    receipt.clientInfo?.nbNumber ||
                    receipt.clientInfo?.referenceNumber ||
                    receipt.clientReferenceNumber ||
                    receipt.metadata?.nbNumber ||
                    '';
                const medicinesList = getItemsPurchased(receipt).join('; ') || 'N/A';
                rows.push(
                    [
                        receipt.id || receipt.saleNumber || '',
                        date,
                        receipt.clientName || receipt.customerName || receipt.clientInfo?.fullName || 'N/A',
                        nbNumber || 'N/A',
                        receipt.customerPhone || receipt.clientInfo?.phone || 'N/A',
                        receipt.customerEmail || receipt.clientInfo?.email || 'N/A',
                        receipt.soldBy || receipt.consultant || receipt.metadata?.soldBy || 'N/A',
                        (receipt.paymentMethod || 'N/A').toUpperCase(),
                        `N$${Number(totalAmount).toFixed(2)}`,
                        medicinesList
                    ]
                        .map(csvEscape)
                        .join(',')
                );
            });
            return rows.join('\n');
        }

        // Generic renderer for inventory breakdown tables using dynapharm_inventory
        function renderInventoryBreakdown(targetId, branchId = 'all') {
            const el = document.getElementById(targetId);
            if (!el) return;
            let inv = {};
            try { inv = JSON.parse(localStorage.getItem('dynapharm_inventory') || '{}'); } catch (e) { inv = {}; }
            const entries = Object.keys(inv).map(name => ({
                name,
                qty: parseFloat(inv[name]?.currentStock || 0),
                reorder: inv[name]?.reorderLevel ?? 5
            }));
            if (entries.length === 0) {
                el.innerHTML = '<p style="text-align:center; color:#7f8c8d; padding:20px;">No inventory records found.</p>';
                return;
            }
            const rows = entries.map(e => {
                const low = e.qty <= e.reorder;
                return `
                    <tr>
                        <td style="padding:10px; border:1px solid #ddd;">${e.name}</td>
                        <td style="padding:10px; border:1px solid #ddd; text-align:right; font-weight:700; color:${low ? '#e74c3c' : '#27ae60'};">${e.qty}</td>
                        <td style="padding:10px; border:1px solid #ddd; text-align:right;">${e.reorder}</td>
                        <td style="padding:10px; border:1px solid #ddd;">${low ? '⚠️ Low' : '✅ OK'}</td>
                    </tr>`;
            }).join('');
            el.innerHTML = `
                <div style="overflow-x:auto;">
                    <table style="width:100%; border-collapse:collapse; background:white;">
                        <thead>
                            <tr style="background:#c41e3a; color:white;">
                                <th style="padding:12px; text-align:left; border:1px solid #ddd;">Product</th>
                                <th style="padding:12px; text-align:right; border:1px solid #ddd;">Qty</th>
                                <th style="padding:12px; text-align:right; border:1px solid #ddd;">Reorder</th>
                                <th style="padding:12px; text-align:left; border:1px solid #ddd;">Status</th>
                            </tr>
                        </thead>
                        <tbody>${rows}</tbody>
                    </table>
                </div>`;
        }

        function printMISReport() {
            window.print();
        }

        function renderMISBranchDailySummary(reportsToDisplay) {
            const container = document.getElementById('misBranchDailySummary');
            if (!container) return;
            if (!reportsToDisplay || reportsToDisplay.length === 0) {
                container.innerHTML = '<p style="text-align: center; color: #7f8c8d;">No data for selected range.</p>';
                return;
            }
            const groups = {};
            reportsToDisplay.forEach(r => {
                const branch = r.branch || r.clientInfo?.branch || 'Unknown';
                if (!groups[branch]) {
                    groups[branch] = { count: 0, total: 0 };
                }
                groups[branch].count += 1;
                groups[branch].total += calculateReportTotal(r);
            });
            let html = '<table style="width: 100%; border-collapse: collapse;">\n<thead>\n<tr style="background: #2c3e50; color: white;">\n<th style="padding: 10px; text-align: left; border: 1px solid #ddd;">Branch</th>\n<th style="padding: 10px; text-align: left; border: 1px solid #ddd;">Receipts</th>\n<th style="padding: 10px; text-align: left; border: 1px solid #ddd;">Total Amount</th>\n</tr>\n</thead><tbody>';
            Object.entries(groups).forEach(([branch, stats], i) => {
                const rowColor = i % 2 === 0 ? '#f8f9fa' : 'white';
                html += `<tr style="background: ${rowColor};"><td style="padding: 10px; border: 1px solid #ddd;">${branch}</td><td style="padding: 10px; border: 1px solid #ddd;">${stats.count}</td><td style="padding: 10px; border: 1px solid #ddd; font-weight: bold;">N$${stats.total.toFixed(2)}</td></tr>`;
            });
            html += '</tbody></table>';
            container.innerHTML = html;
        }

        function calculateAge() {
            const dob = document.querySelector('[name="dob"]').value;
            if (dob) {
                const age = Math.floor((new Date() - new Date(dob)) / 31536000000);
                document.getElementById('age').value = age;
            }
        }

        function selectNA(fieldName) {
            const checkboxes = document.querySelectorAll(`[name="${fieldName}"]`);
            checkboxes.forEach(cb => cb.checked = false);
            document.getElementById('mh_na').checked = true;
        }

        // Toggle diet options visibility based on user selection
        function toggleDietOptions() {
            try {
                const dietYes = document.getElementById('dietYes');
                const dietNo = document.getElementById('dietNo');
                const dietOptions = document.getElementById('dietOptions');
                const dietOther = document.querySelector('input[name="dietOther"]');
                
                if (!dietOptions) {
                    return;
                }
                
                // Show diet options if "Yes" is selected, hide if "No" is selected
                if (dietYes && dietYes.checked) {
                    dietOptions.style.display = 'block';
                    if (dietOther) {
                        dietOther.style.display = 'block';
                        dietOther.style.marginTop = '10px';
                    }
                    // Make selection required when visible
                    dietOptions.setAttribute('required', 'required');
                } else if (dietNo && dietNo.checked) {
                    dietOptions.style.display = 'none';
                    if (dietOther) {
                        dietOther.style.display = 'none';
                        dietOther.value = '';
                    }
                    // Clear selections when hidden
                    const options = dietOptions.querySelectorAll('option');
                    options.forEach(opt => opt.selected = false);
                    dietOptions.removeAttribute('required');
                }
            } catch (error) {
                console.error('❌ Error in toggleDietOptions:', error);
            }
        }
        
        // Make function globally accessible for inline event handlers
        if (typeof window !== 'undefined') {
            window.toggleDietOptions = toggleDietOptions;
            window.renderMISAnalytics = renderMISAnalytics;
        }

        // Enhanced signature with camera support
        function signDocument() {
            if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
                // Check if user wants to use camera or enter text
                const useCamera = confirm('Would you like to capture signature using camera? (Click OK for camera, Cancel for text input)');
                if (useCamera) {
                    captureSignatureWithCamera();
                } else {
            const name = prompt('Enter your full name for signature:');
            if (name) {
                document.getElementById('signatureField').value = name;
                document.getElementById('signaturePad').innerHTML = `Signed: ${name}<br>${new Date().toLocaleString()}`;
                document.getElementById('signaturePad').style.background = '#e8f5e9';
                    }
                }
            } else {
                const name = prompt('Enter your full name for signature:');
                if (name) {
                    document.getElementById('signatureField').value = name;
                    document.getElementById('signaturePad').innerHTML = `Signed: ${name}<br>${new Date().toLocaleString()}`;
                    document.getElementById('signaturePad').style.background = '#e8f5e9';
                }
            }
        }

        function captureSignatureWithCamera() {
            const video = document.createElement('video');
            video.style.width = '100%';
            video.style.maxWidth = '400px';
            video.autoplay = true;
            video.playsInline = true;

            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');

            const modal = document.createElement('div');
            modal.style.cssText = 'position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.8); z-index: 10000; display: flex; flex-direction: column; align-items: center; justify-content: center;';
            
            const container = document.createElement('div');
            container.style.cssText = 'background: white; padding: 20px; border-radius: 10px; max-width: 90%;';

            const controls = document.createElement('div');
            controls.style.cssText = 'margin-top: 15px; display: flex; gap: 10px; justify-content: center;';

            const captureBtn = document.createElement('button');
            captureBtn.className = 'btn btn-success';
            captureBtn.textContent = '📷 Capture';
            captureBtn.onclick = () => {
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                ctx.drawImage(video, 0, 0);
                const dataURL = canvas.toDataURL('image/png');
                document.getElementById('signatureField').value = 'Signature captured';
                document.getElementById('signaturePad').innerHTML = `<img src="${dataURL}" style="max-width: 100%; border-radius: 5px;" alt="Signature"><br>Captured: ${new Date().toLocaleString()}`;
                document.getElementById('signaturePad').style.background = '#e8f5e9';
                // Store signature image
                localStorage.setItem('lastSignature', dataURL);
                stopCamera();
            };

            const cancelBtn = document.createElement('button');
            cancelBtn.className = 'btn btn-danger';
            cancelBtn.textContent = 'Cancel';
            cancelBtn.onclick = stopCamera;

            controls.appendChild(captureBtn);
            controls.appendChild(cancelBtn);
            container.appendChild(video);
            container.appendChild(controls);
            modal.appendChild(container);
            document.body.appendChild(modal);

            navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } })
                .then(stream => {
                    video.srcObject = stream;
                    window.captureStream = stream;
                })
                .catch(err => {
                    alert('Camera access denied. Please enter signature manually.');
                    document.body.removeChild(modal);
                });

            function stopCamera() {
                if (window.captureStream) {
                    window.captureStream.getTracks().forEach(track => track.stop());
                }
                if (document.body.contains(modal)) {
                    document.body.removeChild(modal);
                }
            }
        }

        function handleConsentChange() {
            const consentCheck = document.getElementById('consentCheck');
            const fullName = document.querySelector('input[name="fullName"]').value.trim();
            
            if (consentCheck.checked && fullName) {
                // Auto-fill signature with client's name
                document.getElementById('signatureField').value = fullName;
                document.getElementById('signaturePad').innerHTML = `Signed: ${fullName}<br>${new Date().toLocaleString()}`;
                document.getElementById('signaturePad').style.background = '#e8f5e9';
            } else if (!consentCheck.checked) {
                // Clear signature if consent is unchecked
                document.getElementById('signatureField').value = '';
                document.getElementById('signaturePad').innerHTML = 'Click here to sign electronically';
                document.getElementById('signaturePad').style.background = '#f0f8ff';
            }
        }

