async function logoutRequest() {
    try {
        await fetch('/api/auth/logout', {
            method: 'POST',
            credentials: 'include'
        });
    } catch (_) {}
}

function isPortalAllowedForRole(role, portal) {
    const normalizedRole = (role || '').toLowerCase();
    if (!normalizedRole) return false;
    if (normalizedRole === 'admin') return true;
    const allowed = ROLE_PORTAL_ACCESS[normalizedRole] || [];
    return allowed.includes(portal);
}

function setAuthenticatedUser(user) {
    currentUser = { ...user };
    if (currentUser && typeof currentUser === 'object') {
        try {
            delete currentUser.password;
            delete currentUser.password_hash;
        } catch (_) {}
    }
    // Always sync to window.currentUser for global access
    window.currentUser = currentUser;
    // Also ensure local variable is set
    if (typeof currentUser !== 'undefined') {
        currentUser = window.currentUser;
    }
    if (Array.isArray(users)) {
        const existingIndex = users.findIndex(u => u.id === currentUser.id);
        if (existingIndex >= 0) {
            const merged = { ...users[existingIndex], ...currentUser };
            delete merged.password;
            delete merged.password_hash;
            users[existingIndex] = merged;
                } else {
            users.push({ ...currentUser });
        }
    }
    // Database API only - currentUser stored in memory only, not localStorage
    // try { localStorage.setItem('currentUser', JSON.stringify(currentUser)); } catch (_) {}
    const normalizedRole = (user.role || 'guest').toLowerCase();
    setCurrentUserRole(normalizedRole);
}

function handlePortalLoginSuccess(user, options = {}) {
    setAuthenticatedUser(user);
    const role = (user.role || '').toLowerCase();
    
    // Check if warehouse manager and set filter
    if (role === 'warehouse_manager_ondangwa' || role === 'warehouse_manager_windhoek') {
        currentWarehouseFilter = WAREHOUSE_ASSIGNMENTS[role] || null;
        if (currentWarehouseFilter) {
            localStorage.setItem('warehouseFilter', currentWarehouseFilter);
            applyWarehouseFilter();
        }
    }
    
    hideLandingPage();
    showAuthorizedPortals(role);
    updateNavigationForUser(user, role);

    // Protect currentPortal after login - restore if it was reset
    if (window.currentPortal == null && currentPortal) {
        console.warn("Portal reset detected — restoring portal:", currentPortal);
        window.currentPortal = currentPortal;
    }
    if (currentPortal == null && window.currentPortal) {
        console.warn("Portal reset detected — restoring portal:", window.currentPortal);
        currentPortal = window.currentPortal;
    }
    
    var portal = currentPortal || window.currentPortal;
    
    if (!portal || portal === 'default') {
        try {
            var savedPortal = localStorage.getItem('dynapharm_active_portal');
            if (savedPortal) {
                var allowed = ROLE_PORTAL_ACCESS[role] || ['client'];
                if (role === 'admin' || allowed.includes(savedPortal)) {
                    portal = savedPortal;
                }
            }
        } catch(e) {}
    }
    
    var roleDefaultPortal = getDefaultPortalForRole(role);
    
    if (!portal || portal === 'default' || portal === 'dispenser' || portal === '__staff_login__') {
        portal = roleDefaultPortal || 'client';
    }
    
    
    // Hide only the known portal-level Auth/Content wrappers (not sub-elements inside portals)
    // openTab() will correctly show/hide these when navigating to a portal
    var _PORTAL_PAIRS = ['consultant', 'dispenser', 'stock', 'gm', 'director', 'admin', 'mis'];
    _PORTAL_PAIRS.forEach(function(p) {
        var a = document.getElementById(p + 'Auth');
        var c = document.getElementById(p + 'Content');
        if (a) a.style.display = 'none';
        if (c) c.style.display = 'none';
    });
    
    // Show ONLY the portal that matches currentPortal
    if (portal) {
        // Use openTab to properly open the portal tab
        if (typeof openTab === 'function') {
            openTab(portal, null);
        } else {
            // Fallback: manually open the tab
            const portalTab = document.getElementById(portal);
            if (portalTab) {
                document.querySelectorAll('.tab-content').forEach(function(t) {
                    t.classList.remove('active');
                });
                portalTab.classList.add('active');
                
                var ptDiv = document.getElementById('portalTabs');
                if (ptDiv) {
                    ptDiv.querySelectorAll(':scope > .tab-button').forEach(function(btn) {
                        btn.classList.remove('active');
                        var onc = btn.getAttribute('onclick') || '';
                        if (onc.indexOf("'" + portal + "'") !== -1) {
                            btn.classList.add('active');
                        }
                    });
                }
            }
        }
        
        // Then show/hide Auth and Content containers (if they exist)
        const authElement = document.getElementById(portal + 'Auth');
        const contentElement = document.getElementById(portal + 'Content');
        if (authElement) authElement.style.display = 'none';
        if (contentElement) contentElement.style.display = 'block';
    }

    try {
        if ((portal === 'consultant' || portal === 'dispenser')) {
                    if (!currentBranch || currentBranch === '') {
                        if (user.branch) {
                            currentBranch = user.branch;
                        } else if (Array.isArray(user.branches) && user.branches.length > 0) {
                            currentBranch = user.branches[0];
                }
                const branchSelect = document.getElementById('branchSelect');
                if (branchSelect && currentBranch) branchSelect.value = currentBranch;
                const checkupBranchSelect = document.getElementById('checkupBranchSelect');
                if (checkupBranchSelect && currentBranch) checkupBranchSelect.value = currentBranch;
            }
        }
    } catch (_) {}

            setTimeout(() => {
        try {
                startAutoRefresh();
                showRealtimeStatus();
        } catch (_) {}
    }, 1000);

    const branchName = branches.find(b => b.id === user.branch)?.name || user.branch || 'Unknown';
    if (portal) {
        const profile = document.getElementById(portal + 'Profile');
        if (profile) {
                profile.innerHTML = `
                <h4>Welcome, ${user.fullName || user.username}</h4>
                    <p>Role: ${user.role} | Branch: ${branchName}</p>
                    <button class="btn btn-warning" onclick="showChangePassword()">Change Password</button>
                    <button class="btn btn-danger" onclick="logout()">Logout</button>
                `;
        }
            }
            
    // Load portal-specific dashboard data
    if (portal === 'consultant') {
        refreshConsultantData({ forceAppointments: true }).catch(err => {
        });
    } else if (portal === 'dispenser') {
        displayPrescriptions();
        displayPriceList();
        showDispenserTab('walkIn');
    } else if (portal === 'mis') {
        loadMISBranches();
        displayMISReports();
    } else if (portal === 'admin') {
        loadUserList();
        loadBranchListAdmin();
        populatePhotoProductSelect();
        loadProductPhotos().then(() => renderProductPhotos());
        loadAdminDistributorDirectory();
    } else if (portal === 'stock') {
        // Stock portal initialization
        if (typeof loadStockData === 'function') {
            loadStockData();
        }
    } else if (portal === 'finance') {
        // Finance portal initialization
        if (typeof ensureFinancePortalInitialized === 'function') {
            ensureFinancePortalInitialized();
        }
        if (typeof refreshFinancialDashboard === 'function') {
            refreshFinancialDashboard(true).catch(err => {
            });
        }
    } else if (portal === 'hr-portal') {
        // HR portal initialization
        if (typeof loadHRData === 'function') {
            loadHRData();
        }
    } else if (portal === 'gm') {
        // GM portal initialization
        if (typeof loadGMData === 'function') {
            loadGMData();
        }
    } else if (portal === 'director') {
        // Director portal initialization
        if (typeof loadDirectorData === 'function') {
            loadDirectorData();
        }
    } else if (portal === 'frontdesk') {
        // Front desk portal initialization
        if (typeof loadFrontDeskData === 'function') {
            loadFrontDeskData();
        }
    } else if (portal === 'client') {
        // Client portal initialization
        if (typeof loadClientData === 'function') {
            loadClientData();
        }
    }
            
    if (!options.silent) {
        try {
            alert(`Welcome, ${user.fullName || user.username}! Real-time sync activated.`);
        } catch (_) {}
    }
}

