// SHOP: Inline cart + product loading for portal page (main.js not loaded here)
// =============================================================================
if (typeof window.addToShopCart !== 'function') {
    window._shopCart = window._shopCart || [];
    window._updateShopCartDisplay = function() {
        var cart = window._shopCart;
        var total = cart.reduce(function(sum, i) { return sum + i.price * i.qty; }, 0);
        function renderCart(itemsEl, totalEl, sectionEl) {
            if (!itemsEl) return;
            if (cart.length === 0) { if (sectionEl) sectionEl.style.display = 'none'; return; }
            if (sectionEl) sectionEl.style.display = 'block';
            itemsEl.innerHTML = cart.map(function(item) {
                var safeKey = item.key.replace(/'/g, "\\'");
                return '<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid #eee;">' +
                    '<div><strong>' + item.name + '</strong><br><span style="color:#666;font-size:0.9rem;">N$ ' + item.price.toFixed(2) + ' &times; ' + item.qty + '</span></div>' +
                    '<div style="display:flex;align-items:center;gap:8px;">' +
                    '<span style="font-weight:700;color:#c41e3a;">N$ ' + (item.price * item.qty).toFixed(2) + '</span>' +
                    '<button onclick="window._removeShopCartItem(\'' + safeKey + '\')" style="background:#e74c3c;color:white;border:none;padding:4px 8px;border-radius:4px;cursor:pointer;font-size:0.75rem;">\u2715</button>' +
                    '</div></div>';
            }).join('');
            if (totalEl) totalEl.textContent = 'N$ ' + total.toFixed(2);
        }
        renderCart(document.getElementById('shopCartItems'), document.getElementById('shopCartTotal'), document.getElementById('shopCartSection'));
        renderCart(document.getElementById('landingShopCartItems'), document.getElementById('landingShopCartTotal'), document.getElementById('landingShopCartSection'));
    };
    window._removeShopCartItem = function(key) {
        window._shopCart = window._shopCart.filter(function(i) { return i.key !== key; });
        window._updateShopCartDisplay();
    };
    window.clearShopCart = function() {
        window._shopCart = [];
        window._updateShopCartDisplay();
    };
    window.addToShopCart = function(productName, cp, dp, bv, key, btnEl) {
        var price = parseFloat(cp) || parseFloat(dp) || 0;
        var itemKey = key || productName;
        var existing = window._shopCart.find(function(i) { return i.key === itemKey; });
        if (existing) {
            existing.qty += 1;
        } else {
            window._shopCart.push({ name: productName, price: price, cp: parseFloat(cp)||0, dp: parseFloat(dp)||0, bv: parseFloat(bv)||0, qty: 1, key: itemKey });
        }
        window._updateShopCartDisplay();
        if (btnEl) {
            var orig = btnEl.textContent;
            btnEl.textContent = '\u2713 Added';
            btnEl.style.background = '#27ae60';
            setTimeout(function() { btnEl.textContent = orig; btnEl.style.background = '#c41e3a'; }, 1200);
        }
    };
}

if (typeof window.loadShopProducts !== 'function') {
    window.loadShopProducts = async function loadShopProducts() {
        var grids = [
            document.getElementById('shopProductsGrid'),
            document.getElementById('landingShopProductsGrid')
        ].filter(Boolean);
        if (grids.length === 0) return;
        grids.forEach(function(g) { g.innerHTML = '<p style="text-align:center;color:#999;">Loading products...</p>'; });
        try {
            var resp = await fetch('/api/products');
            if (!resp.ok) throw new Error('API error ' + resp.status);
            var products = await resp.json();
            if (!Array.isArray(products) || products.length === 0) {
                grids.forEach(function(g) { g.innerHTML = '<p style="text-align:center;color:#999;">No products available.</p>'; });
                return;
            }
            function escHtml(str) {
                var d = document.createElement('div');
                d.textContent = str;
                return d.innerHTML;
            }
            var html = '';
            products.forEach(function(p) {
                var name = escHtml(p.name || p.description || 'Product');
                var price = p.cp || p.dp || '0.00';
                var dp = p.dp || price;
                var category = escHtml(p.category || '');
                var imgSrc = (p.images && p.images.length > 0) ? (p.images[0].image_data || p.images[0].image_url || '') : '';
                var safeImgSrc = escHtml(imgSrc);
                var imgHtml = imgSrc
                    ? '<img src="' + safeImgSrc + '" alt="' + name + '" style="width:100%;height:180px;object-fit:contain;background:#f9f9f9;" onerror="this.style.display=\'none\'">'
                    : '<div style="width:100%;height:180px;background:#f0f0f0;display:flex;align-items:center;justify-content:center;color:#ccc;font-size:3rem;">📦</div>';
                var safeKey = escHtml((p.id || '').toString()).replace(/'/g, "\\'");
                var safeName = (p.name || p.description || 'Product').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
                var pCp = parseFloat(p.cp || p.dp || 0);
                var pDp = parseFloat(p.dp || p.cp || 0);
                var pBv = parseFloat(p.bv || 0);
                html += '<div class="product-card" style="background:white;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.1);transition:transform 0.2s;">' +
                    imgHtml +
                    '<div style="padding:15px;">' +
                        '<h4 style="margin:0 0 8px;font-size:0.95rem;color:#333;">' + name + '</h4>' +
                        (category ? '<span style="font-size:0.75rem;background:#f0f0f0;padding:2px 8px;border-radius:10px;color:#666;">' + category + '</span>' : '') +
                        '<div style="margin-top:10px;display:flex;justify-content:space-between;align-items:center;">' +
                            '<div><span style="font-weight:700;color:#c41e3a;font-size:1.1rem;">N$ ' + parseFloat(price).toFixed(2) + '</span>' +
                            (dp !== price ? '<br><span style="font-size:0.8rem;color:#666;">DP: N$ ' + parseFloat(dp).toFixed(2) + '</span>' : '') + '</div>' +
                            '<button onclick="addToShopCart(\'' + safeName + '\',' + pCp + ',' + pDp + ',' + pBv + ',\'' + safeKey + '\',this)" class="btn" style="background:#c41e3a;color:white;border:none;padding:8px 12px;border-radius:6px;cursor:pointer;font-size:0.85rem;">Add to Cart</button>' +
                        '</div>' +
                    '</div></div>';
            });
            grids.forEach(function(g) { g.innerHTML = html; });
        } catch(err) {
            console.error('[SHOP] Load error:', err);
            grids.forEach(function(g) { g.innerHTML = '<p style="text-align:center;color:#c41e3a;">Failed to load products. Please refresh.</p>'; });
        }
    };
}

