function switchStaffAuthTab(tab) {
    var loginBtn = document.getElementById('staffTabLogin');
    var signupBtn = document.getElementById('staffTabSignup');
    var loginFormEl = document.getElementById('loginForm');
    var signupFormEl = document.getElementById('staffSignupForm');
    if (tab === 'signup') {
        if (loginBtn) { loginBtn.style.borderBottomColor = 'transparent'; loginBtn.style.color = '#999'; }
        if (signupBtn) { signupBtn.style.borderBottomColor = '#c41e3a'; signupBtn.style.color = '#c41e3a'; }
        if (loginFormEl) loginFormEl.style.display = 'none';
        if (signupFormEl) signupFormEl.style.display = 'block';
    } else {
        if (loginBtn) { loginBtn.style.borderBottomColor = '#c41e3a'; loginBtn.style.color = '#c41e3a'; }
        if (signupBtn) { signupBtn.style.borderBottomColor = 'transparent'; signupBtn.style.color = '#999'; }
        if (loginFormEl) loginFormEl.style.display = 'block';
        if (signupFormEl) signupFormEl.style.display = 'none';
    }
    var ids = ['loginError', 'signupError', 'signupSuccess'];
    ids.forEach(function(id) { var el = document.getElementById(id); if (el) { el.textContent = ''; el.style.display = (id === 'signupSuccess') ? 'none' : ''; } });
}

var staffSignupForm = document.getElementById('staffSignupForm');
if (staffSignupForm) {
    staffSignupForm.addEventListener('submit', async function(e) {
        e.preventDefault();
        var fullName = (document.getElementById('regFullName').value || '').trim();
        var username = (document.getElementById('regUsername') ? document.getElementById('regUsername').value || '' : '').trim().toLowerCase();
        var dob = document.getElementById('regDOB').value;
        var email = (document.getElementById('regEmail').value || '').trim();
        var role = document.getElementById('regRole').value;
        var pw = document.getElementById('regPassword').value;
        var confirmPw = document.getElementById('regConfirmPassword').value;
        var errEl = document.getElementById('signupError');
        var successEl = document.getElementById('signupSuccess');
        if (errEl) { errEl.textContent = ''; }
        if (successEl) { successEl.style.display = 'none'; successEl.textContent = ''; }

        if (!fullName || !dob || !role || !pw) {
            if (errEl) errEl.textContent = 'Please fill in all required fields.';
            return;
        }
        if (!username) {
            if (errEl) errEl.textContent = 'Please enter a username.';
            return;
        }
        if (!/^[a-z0-9._-]+$/.test(username)) {
            if (errEl) errEl.textContent = 'Username may only contain letters, numbers, dots, underscores, or hyphens.';
            return;
        }
        if (pw.length < 6) {
            if (errEl) errEl.textContent = 'Password must be at least 6 characters.';
            return;
        }
        if (pw !== confirmPw) {
            if (errEl) errEl.textContent = 'Passwords do not match.';
            return;
        }

        var btn = e.target.querySelector('button[type="submit"]');
        var origText = btn ? btn.textContent : 'Create Account';
        if (btn) { btn.disabled = true; btn.textContent = 'Please wait...'; }

        try {
            var res = await fetch('/api/auth/register', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ full_name: fullName, username: username, dob: dob, email: email, role: role, password: pw })
            });
            var data = await res.json();
            if (!res.ok) {
                if (errEl) errEl.textContent = data.error || 'Registration failed. Please try again.';
                if (btn) { btn.disabled = false; btn.textContent = origText; }
                return;
            }
            var assignedUsername = data.username || username;
            if (successEl) {
                successEl.textContent = (data.message || 'Account created successfully!') + ' Login username: ' + assignedUsername;
                successEl.style.display = 'block';
            }
            // Auto-populate HR portal employee list
            try {
                var hrPayload = {
                    name: fullName,
                    role: role,
                    email: email,
                    username: assignedUsername,
                    hireDate: new Date().toISOString().split('T')[0],
                    employmentType: 'full-time',
                    status: 'active',
                    notes: 'Auto-registered via staff signup'
                };
                await fetch('/api/employees', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(hrPayload)
                });
                // Refresh HR employee list if portal is currently open
                if (typeof loadEmployeesData === 'function') { loadEmployeesData().catch(function(){}); }
            } catch(hrErr) { console.warn('HR auto-populate warning:', hrErr); }
            e.target.reset();
            if (btn) { btn.disabled = false; btn.textContent = origText; }
        } catch (err) {
            if (errEl) errEl.textContent = 'Connection error. Please try again.';
            if (btn) { btn.disabled = false; btn.textContent = origText; }
        }
    });
}

if (loginForm) {
    loginForm.addEventListener('submit', async function(e) {
        e.preventDefault();
        if (!currentPortal) {
            if (loginError) loginError.textContent = 'Please select a portal to continue.';
            return;
        }
        const usernameField = document.getElementById('username');
        const passwordField = document.getElementById('password');
        const username = usernameField ? usernameField.value.trim() : '';
        const password = passwordField ? passwordField.value || '' : '';
        if (!username || !password) {
            if (loginError) loginError.textContent = 'Username and password are required.';
            if (!username && usernameField) usernameField.focus();
            else if (passwordField) passwordField.focus();
            return;
        }
        if (loginError) loginError.textContent = '';
        const originalButtonText = loginSubmitButton ? loginSubmitButton.textContent : 'Login';
        if (loginSubmitButton) {
            loginSubmitButton.disabled = true;
            loginSubmitButton.textContent = 'Signing in...';
        }
        try {
            const data = await loginPortalRequest(username, password);
            const user = data?.user;
            if (!user) {
                throw new Error('Unexpected response from server.');
            }
            if (currentPortal === '__staff_login__') {
                currentPortal = getDefaultPortalForRole(user.role);
                window.currentPortal = currentPortal;
            } else if (!isPortalAllowedForRole(user.role, currentPortal)) {
                await logoutRequest();
                if (loginError) loginError.textContent = `The ${getPortalLabel(currentPortal)} portal is not available for the ${user.role} role.`;
                if (passwordField) {
                    passwordField.value = '';
                    passwordField.focus();
                }
                return;
            }
            handlePortalLoginSuccess(user);
            closeLoginModal();
            
            // SECURITY: Ensure URL is clean after login (no username/password parameters)
            try {
                const currentUrl = new URL(window.location.href);
                if (currentUrl.searchParams.has('username') || currentUrl.searchParams.has('password')) {
                    currentUrl.searchParams.delete('username');
                    currentUrl.searchParams.delete('password');
                    const cleanUrl = currentUrl.pathname + (currentUrl.search ? currentUrl.search : '') + (currentUrl.hash ? currentUrl.hash : '');
                    window.history.replaceState({}, '', cleanUrl);
                    console.warn('Cleaned sensitive login parameters from URL after login');
                }
            } catch(_) {}
        } catch (error) {
            if (loginError) loginError.textContent = error.message || 'Unable to login. Please try again.';
            if (passwordField) {
                passwordField.value = '';
                passwordField.focus();
            }
        } finally {
            if (loginSubmitButton) {
                loginSubmitButton.disabled = false;
                loginSubmitButton.textContent = originalButtonText;
            }
        }
    });
}

