        function switchConsultantSection(section) {
            var sections = ['checkups', 'clients', 'reports', 'followups', 'analytics'];
            var mainSection = document.getElementById('consultantMainSection');
            var staffSection = document.getElementById('consultantStaffSection');

            document.querySelectorAll('.consultant-nav-btn').forEach(function(btn) {
                btn.style.color = '#64748b';
                btn.style.borderBottom = '3px solid transparent';
                btn.classList.remove('consultant-nav-active');
            });

            var activeBtn = document.getElementById('consultantNav' + section.charAt(0).toUpperCase() + section.slice(1));
            if (activeBtn) {
                activeBtn.style.color = '#c41e3a';
                activeBtn.style.borderBottom = '3px solid #c41e3a';
                activeBtn.classList.add('consultant-nav-active');
            }

            if (section === 'staff') {
                if (mainSection) mainSection.style.display = 'none';
                if (staffSection) staffSection.style.display = 'block';
                if (typeof refreshStaffServices === 'function') refreshStaffServices('consultant');
                return;
            }

            if (mainSection) mainSection.style.display = 'block';
            if (staffSection) staffSection.style.display = 'none';

            sections.forEach(function(s) {
                var el = document.getElementById('consultantSection' + s.charAt(0).toUpperCase() + s.slice(1));
                if (el) el.style.display = (s === section) ? 'block' : 'none';
            });
        }

