function recalcPaymentTotals(){
    if (!rxPaymentContext) return;
    const discount = Number(document.getElementById('paymentDiscount')?.value||0);
    const amountDue = Math.max(0, Number(rxPaymentContext.amountDue||0) - discount);
    const tenderInputs = Array.from(document.querySelectorAll('#tenderRows .tender-amount'));
    const tenderTotal = tenderInputs.reduce((sum, el) => sum + (Number(el.value)||0), 0);
    const changeOrBalance = tenderTotal - amountDue;
    const amountDueEl = document.getElementById('amountDue');
    const tenderTotalEl = document.getElementById('tenderTotal');
    const changeBalanceEl = document.getElementById('changeBalance');
    if (amountDueEl) amountDueEl.textContent = rxFormat(amountDue);
    if (tenderTotalEl) tenderTotalEl.textContent = rxFormat(tenderTotal);
    if (changeBalanceEl) changeBalanceEl.textContent = rxFormat(changeOrBalance);
}

function generateReceiptNumber(reportId){
    try {
        const report = reports.find(r => r.id === reportId);
        const client = report ? clients.find(c => c.referenceNumber === report.clientId) : null;
        const branch = client ? (client.branch||'BR') : 'BR';
        const dt = new Date();
        const ymd = dt.toISOString().slice(0,10).replaceAll('-','');
        const seq = (''+Date.now()).slice(-6);
        return `${branch}-${ymd}-${seq}`;
    } catch(_) { return 'RX-'+Date.now(); }
}

async function confirmPayment(){
    if (!rxPaymentContext) return;
    const { reportId } = rxPaymentContext;
    const report = reports.find(r => r.id === reportId);
    if (!report) return;
    const discount = Number(document.getElementById('paymentDiscount')?.value||0);
    const methods = Array.from(document.querySelectorAll('#tenderRows .tender-method'));
    const refs = Array.from(document.querySelectorAll('#tenderRows .tender-ref'));
    const amts = Array.from(document.querySelectorAll('#tenderRows .tender-amount'));
    const tenders = methods.map((m, i) => ({ method: m.value, reference: refs[i]?.value || '', amount: Number(amts[i]?.value||0) }));
    const receipt = generateReceiptNumber(reportId);

    if (!report.payments) report.payments = [];
    report.payments.push({
        receipt,
        discount,
        tenders,
        memberStatus: rxPaymentContext.memberStatus,
        collectedBy: (currentUser && currentUser.fullName) ? currentUser.fullName : 'system',
        collectedAt: new Date().toISOString()
    });

    if (Array.isArray(report.medicines)) {
        report.medicines.forEach(m => {
            if (m.dispensed) {
                if (!m.paymentHistory) m.paymentHistory = [];
                m.paid = true;
                m.paidBy = (currentUser && currentUser.fullName) ? currentUser.fullName : 'system';
                m.paidAt = new Date().toISOString();
                m.paymentMethod = 'Multiple';
                m.amountPaid = tenders.reduce((s, t) => s + (Number(t.amount)||0), 0);
                m.paymentHistory.push({ amount: m.amountPaid, method: 'Multiple', paidBy: m.paidBy, paidAt: m.paidAt, reference: receipt });
            }
        });
    }

    try {
        const result = await apiRequest('/reports', 'PUT', report);
        if (result && result.success) {
            const idx = reports.findIndex(r => r.id === reportId);
            if (idx !== -1) reports[idx] = report;
            closePaymentModal();
            displayPrescriptions();
            alert(`✅ Payment recorded. Receipt: ${receipt}`);
        } else {
            alert('Error saving payment');
        }
    } catch(e){ alert('Error saving payment'); }
}

function viewPrescriptionPaymentHistory(reportId){
    const report = reports.find(r => r.id === reportId);
    if (!report || !report.payments || report.payments.length === 0){
        alert('No prescription-level payments recorded');
        return;
    }
    const lines = report.payments.map(p => {
        const sum = (p.tenders||[]).reduce((s,t)=> s+(Number(t.amount)||0),0);
        const methods = (p.tenders||[]).map(t=> `${t.method}:${(Number(t.amount)||0).toFixed(2)}`).join(', ');
        return `${new Date(p.collectedAt).toLocaleString('en-GB')} | ${p.receipt} | ${methods} | Total: ${sum.toFixed(2)}`;
    }).join('\n');
    alert(`Payment History for ${reportId}:\n\n${lines}`);
}

// FEFO helper: choose earliest-expiring lot with enough qty (or first available)
function pickFefoLot(productName, qty){
    try {
        const inv = (window.inventory && window.inventory[productName]) ? window.inventory[productName] : null;
        const lots = Array.isArray(inv?.lots) ? inv.lots.slice() : [];
        if (lots.length === 0) return null;
        lots.sort((a,b) => new Date(a.expiry) - new Date(b.expiry));
        let chosen = null;
        for (const lot of lots){
            if (Number(lot.qty||0) >= Number(qty||1)) { chosen = lot; break; }
            if (!chosen) chosen = lot; // fallback to first
        }
        if (!chosen) chosen = lots[0];
        // decrement lot qty if tracked
        if (inv && inv.lots) {
            const idx = inv.lots.findIndex(l => l.batch === chosen.batch && l.expiry === chosen.expiry);
            if (idx >= 0) inv.lots[idx].qty = Math.max(0, Number(inv.lots[idx].qty||0) - Number(qty||1));
        }
        return { batch: chosen.batch, expiry: chosen.expiry };
    } catch(_){ return null; }
}

async function dispenseAll(reportId){
    if (!hasActionPermission('dispense')) { alert('You do not have permission to dispense.'); return; }
    const report = reports.find(r => r.id === reportId);
    if (!report || !Array.isArray(report.medicines)) return;
    const confirmAll = confirm('Mark all items as dispensed? This will update package items as given and adjust inventory.');
    if (!confirmAll) return;
    report.medicines.forEach(med => {
        const price = findProductPrice(med.name);
        const isPackage = !!price.isPackage;
        if (isPackage){
            const products = price.products || [];
            med.packageStatus = med.packageStatus || {};
            products.forEach(p => med.packageStatus[p] = 'given');
        }
        try {
            const inv = (window.inventory && window.inventory[med.name]) ? window.inventory[med.name] : null;
            const neededQty = Number(med.quantity || 1);
            const available = inv ? Number(inv.currentStock || 0) : Infinity;
            if (available < neededQty) {
                med.dueOut = Math.max(0, neededQty - available);
                med.dispensed = false;
                return;
            }
        } catch(_){ }
        med.dispensed = true;
        med.dispensedBy = (currentUser && currentUser.fullName) ? currentUser.fullName : 'system';
        med.dispensedAt = new Date().toISOString();
        try { const lot = pickFefoLot(med.name, Number(med.quantity||1)); if (lot) { med.lotBatch = lot.batch; med.lotExpiry = lot.expiry; } } catch(_){ }
        try { adjustInventoryForDispense(report, med, Number(med.quantity||1)); } catch(_){ }
    });
    try {
        const result = await apiRequest('/reports', 'PUT', report);
        if (result && result.success){
            const idx = reports.findIndex(r => r.id === reportId);
            if (idx !== -1) reports[idx] = report;
            displayPrescriptions();
            alert('✅ All eligible items marked as dispensed. Due-outs recorded where stock was insufficient.');
        } else {
            alert('Error updating prescription');
        }
    } catch(e){ alert('Error updating prescription'); }
}

async function reverseLastPrescriptionPayment(reportId){
    const report = reports.find(r => r.id === reportId);
    if (!report || !report.payments || report.payments.length === 0){
        alert('No payments to reverse');
        return;
    }
    const reason = prompt('Enter reversal reason:');
    if (!reason) return;
    const last = report.payments[report.payments.length - 1];
    const reversingTenders = (last.tenders||[]).map(t => ({ method: t.method, reference: (t.reference||'') + ' (REV)', amount: -Math.abs(Number(t.amount)||0) }));
    report.payments.push({
        receipt: last.receipt + '-REV',
        discount: 0,
        tenders: reversingTenders,
        memberStatus: last.memberStatus,
        collectedBy: (currentUser && currentUser.fullName) ? currentUser.fullName : 'system',
        collectedAt: new Date().toISOString(),
        reversalOf: last.receipt,
        reason
    });
    if (Array.isArray(report.medicines)) {
        report.medicines.forEach(m => { if (m.dispensed) { m.paid = false; delete m.paidAt; delete m.paidBy; delete m.paymentMethod; delete m.amountPaid; } });
    }
    try {
        const result = await apiRequest('/reports', 'PUT', report);
        if (result && result.success){
            const idx = reports.findIndex(r => r.id === reportId);
            if (idx !== -1) reports[idx] = report;
            displayPrescriptions();
            alert('✅ Payment reversed');
        } else {
            alert('Error reversing payment');
        }
    } catch(e){ alert('Error reversing payment'); }
}

        async function ensureWalkInDataHydrated(options = {}) {
            const { force = false } = options || {};
            let priceListLoaded = false;
            let distributorsLoadedNow = false;

            if (typeof ensurePriceListHydrated === 'function') {
                try {
                    await ensurePriceListHydrated(force);
                    priceListLoaded = Array.isArray(window.PRICE_LIST) && window.PRICE_LIST.length > 0;
                } catch (err) {
                    console.warn('ensureWalkInDataHydrated: price list hydration failed', err);
                }
            }

            if (typeof loadDistributors === 'function') {
                try {
                    const list = await loadDistributors({ forceRefresh: force });
                    distributorsLoadedNow = Array.isArray(list) && list.length > 0;
                } catch (err) {
                    console.warn('ensureWalkInDataHydrated: distributor load failed', err);
                }
            }

            if (priceListLoaded && typeof updateWalkInPriceListInsights === 'function') {
                try { updateWalkInPriceListInsights(); } catch (err) { console.debug('updateWalkInPriceListInsights failed', err); }
            }
            if ((distributorsLoadedNow || (Array.isArray(window.distributors) && window.distributors.length > 0)) && typeof updateWalkInDistributorInsights === 'function') {
                try { updateWalkInDistributorInsights(); } catch (err) { console.debug('updateWalkInDistributorInsights failed', err); }
            }
            if (typeof refreshDistributorCustomerHelper === 'function') {
                try { refreshDistributorCustomerHelper(); } catch (_) {}
            }
        }

        // =============================================================================
        // CUSTOMER TYPE CHANGE HANDLERS (Walk-in & Front Desk)
        // =============================================================================
        
        function onCustomerTypeChange() {
            const walkInType = document.getElementById('walkInCustomerType');
            const clientType = document.getElementById('clientTypeSelect');
            
            if (walkInType) {
                const customerReferralField = document.getElementById('customerReferralField');
                if (walkInType.value === 'customer') {
                    if (customerReferralField) customerReferralField.style.display = 'block';
                } else if (walkInType.value === 'distributor') {
                    if (customerReferralField) customerReferralField.style.display = 'none';
                }
            }
            
            if (clientType && typeof handleMembershipStatusChange === 'function') {
                handleMembershipStatusChange();
            }
        }
        window.onCustomerTypeChange = onCustomerTypeChange;
        
        function onFrontDeskCustomerTypeChange() {
            const fdClientType = document.getElementById('fdClientType');
            const fdCustomerReferralSection = document.getElementById('fdCustomerReferralSection');
            const fdDistributorNbSection = document.getElementById('fdDistributorNbSection');
            const fdClientReferral = document.getElementById('fdClientReferral');
            const fdDistributorNB = document.getElementById('fdDistributorNB');
            if (!fdClientType) return;
            
            const type = fdClientType.value;
            if (type === 'customer') {
                if (fdCustomerReferralSection) fdCustomerReferralSection.style.display = 'block';
                if (fdDistributorNbSection) fdDistributorNbSection.style.display = 'none';
                if (fdClientReferral) fdClientReferral.required = true;
                if (fdDistributorNB) fdDistributorNB.required = false;
            } else if (type === 'distributor') {
                if (fdCustomerReferralSection) fdCustomerReferralSection.style.display = 'none';
                if (fdDistributorNbSection) fdDistributorNbSection.style.display = 'block';
                if (fdClientReferral) fdClientReferral.required = false;
                if (fdDistributorNB) fdDistributorNB.required = true;
            } else {
                if (fdCustomerReferralSection) fdCustomerReferralSection.style.display = 'none';
                if (fdDistributorNbSection) fdDistributorNbSection.style.display = 'none';
                if (fdClientReferral) fdClientReferral.required = false;
                if (fdDistributorNB) fdDistributorNB.required = false;
            }
            
        }
        window.onFrontDeskCustomerTypeChange = onFrontDeskCustomerTypeChange;
        
        // =============================================================================
        // WALK-IN CART + SALES HELPERS
        // =============================================================================
        const WALKIN_SALES_HISTORY_KEY = 'dyna_walkin_sales';
        // ============================================================
        // WALK-IN SALE MODULE (rewritten)
        // ============================================================
        // State
        let _wiType = 'registered';   // 'registered' | 'new'
        let _wiRegClient = null;       // { name, code (NB), phone }
        let _wiRefClient = null;       // referring distributor { name, code }
        let _wiPayment = 'cash';
        let _wiNoReferral = false;

        const _WI_PAY_LABELS = { cash:'Cash', card:'Card Payment', mobile:'Mobile Money', bank:'Bank Transfer' };

        function _wiFmt(v) {
            const n = Number(v) || 0;
            return 'N$ ' + n.toFixed(2);
        }

        // --- Open modal ---
        function showWalkInSaleModal() {
            const modal = document.getElementById('walkInSaleModal');
            if (!modal) { alert('Walk-in sale modal not found. Please refresh.'); return; }

            // Reset state
            _wiType = 'registered';
            _wiRegClient = null;
            _wiRefClient = null;
            _wiPayment = 'cash';
            _wiNoReferral = false;

            // Reset UI
            const form_resets = ['wiRegSearch','wiNewName','wiNewPhone','wiRefSearch','wiProductSearch'];
            form_resets.forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
            const hide_ids = ['wiRegSelected','wiRegDropdown','wiRefSelected','wiRefDropdown'];
            hide_ids.forEach(id => { const el = document.getElementById(id); if (el) el.style.display = 'none'; });
            const noRef = document.getElementById('wiNoReferral');
            if (noRef) noRef.checked = false;

            // Clear cart
            if (window.walkInCartStore && typeof window.walkInCartStore.clear === 'function') {
                window.walkInCartStore.clear();
            } else { window.walkInCart = []; }

            wiSetCustomerType('registered');
            wiRenderProducts('');
            wiRenderCart();
            wiSetPayment('cash');

            modal.style.display = 'block';
            console.log('[WI] Walk-in sale modal opened');
        }

        // --- Customer type toggle ---
        function wiSetCustomerType(type) {
            _wiType = type;
            const regBtn = document.getElementById('wiTypeRegistered');
            const newBtn = document.getElementById('wiTypeNew');
            const regPanel = document.getElementById('wiRegisteredPanel');
            const newPanel = document.getElementById('wiNewPanel');
            const priceMode = document.getElementById('wiPriceMode');

            if (type === 'registered') {
                if (regBtn) { regBtn.style.border='2px solid #3498db'; regBtn.style.background='#ebf5fb'; regBtn.style.color='#1a5276'; }
                if (newBtn) { newBtn.style.border='2px solid #ddd'; newBtn.style.background='#fff'; newBtn.style.color='#444'; }
                if (regPanel) regPanel.style.display = 'block';
                if (newPanel) newPanel.style.display = 'none';
                if (priceMode) { priceMode.textContent = 'DP Prices'; priceMode.style.background='#e8f5e9'; priceMode.style.color='#27ae60'; }
            } else {
                if (newBtn) { newBtn.style.border='2px solid #f39c12'; newBtn.style.background='#fef9e7'; newBtn.style.color='#784212'; }
                if (regBtn) { regBtn.style.border='2px solid #ddd'; regBtn.style.background='#fff'; regBtn.style.color='#444'; }
                if (newPanel) newPanel.style.display = 'block';
                if (regPanel) regPanel.style.display = 'none';
                if (priceMode) { priceMode.textContent = 'CP Prices'; priceMode.style.background='#fef3c7'; priceMode.style.color='#92400e'; }
            }
            // Re-render products with correct price tier
            const searchEl = document.getElementById('wiProductSearch');
            wiRenderProducts(searchEl ? searchEl.value : '');
        }

        // --- Search registered clients ---
        function wiSearchRegistered(term) {
            const dd = document.getElementById('wiRegDropdown');
            if (!dd) return;
            const q = (term || '').trim().toLowerCase();
            if (q.length < 1) { dd.style.display = 'none'; return; }

            const list = Array.isArray(window._allCheckupDistributors) ? window._allCheckupDistributors : [];
            const matches = list.filter(d =>
                (d.name||'').toLowerCase().includes(q) ||
                (d.code||'').toLowerCase().includes(q) ||
                (d.nb||'').toLowerCase().includes(q)
            ).slice(0, 12);

            if (!matches.length) { dd.innerHTML = '<div style="padding:10px;color:#94a3b8;font-size:0.85rem;">No results</div>'; dd.style.display = 'block'; return; }

            dd.innerHTML = matches.map(d => `
                <div onclick="wiSelectRegistered('${(d.code||d.nb||'').replace(/'/g,"\'")}','${(d.name||'').replace(/'/g,"\'")}','${(d.phone||'').replace(/'/g,"\'")}',this)"
                    style="padding:9px 12px;cursor:pointer;border-bottom:1px solid #f1f5f9;font-size:0.88rem;"
                    onmouseover="this.style.background='#f1f5f9'" onmouseout="this.style.background='#fff'">
                    <strong style="color:#1e293b;">${d.name||'Unknown'}</strong>
                    <span style="color:#64748b;margin-left:8px;font-size:0.8rem;">NB: ${d.code||d.nb||'—'}</span>
                    ${d.phone ? '<span style="color:#94a3b8;float:right;font-size:0.8rem;">'+d.phone+'</span>' : ''}
                </div>`).join('');
            dd.style.display = 'block';
        }

        function wiSelectRegistered(code, name, phone) {
            _wiRegClient = { code, name, phone };
            const dd = document.getElementById('wiRegDropdown');
            const srch = document.getElementById('wiRegSearch');
            const sel = document.getElementById('wiRegSelected');
            if (dd) dd.style.display = 'none';
            if (srch) srch.value = name;
            if (sel) {
                const n = document.getElementById('wiRegSelectedName');
                const nb = document.getElementById('wiRegSelectedNB');
                const ph = document.getElementById('wiRegSelectedPhone');
                if (n) n.textContent = name;
                if (nb) nb.textContent = code || '—';
                if (ph) ph.textContent = phone || '—';
                sel.style.display = 'block';
            }
        }

        function wiClearRegistered() {
            _wiRegClient = null;
            const srch = document.getElementById('wiRegSearch');
            const sel = document.getElementById('wiRegSelected');
            if (srch) srch.value = '';
            if (sel) sel.style.display = 'none';
        }

        // --- Search referral distributors ---
        function wiSearchReferral(term) {
            const dd = document.getElementById('wiRefDropdown');
            if (!dd) return;
            const q = (term || '').trim().toLowerCase();
            if (q.length < 1) { dd.style.display = 'none'; return; }

            const list = Array.isArray(window._allCheckupDistributors) ? window._allCheckupDistributors : [];
            const matches = list.filter(d =>
                (d.name||'').toLowerCase().includes(q) ||
                (d.code||'').toLowerCase().includes(q)
            ).slice(0, 12);

            if (!matches.length) { dd.innerHTML = '<div style="padding:10px;color:#94a3b8;font-size:0.85rem;">No results</div>'; dd.style.display = 'block'; return; }

            dd.innerHTML = matches.map(d => `
                <div onclick="wiSelectReferral('${(d.code||'').replace(/'/g,"\'")}','${(d.name||'').replace(/'/g,"\'")}',this)"
                    style="padding:9px 12px;cursor:pointer;border-bottom:1px solid #f1f5f9;font-size:0.88rem;"
                    onmouseover="this.style.background='#f1f5f9'" onmouseout="this.style.background='#fff'">
                    <strong style="color:#1e293b;">${d.name||'Unknown'}</strong>
                    <span style="color:#64748b;margin-left:8px;font-size:0.8rem;">NB: ${d.code||'—'}</span>
                </div>`).join('');
            dd.style.display = 'block';
        }

        function wiSelectReferral(code, name) {
            _wiRefClient = { code, name };
            const dd = document.getElementById('wiRefDropdown');
            const srch = document.getElementById('wiRefSearch');
            const sel = document.getElementById('wiRefSelected');
            if (dd) dd.style.display = 'none';
            if (srch) srch.value = name;
            if (sel) {
                const n = document.getElementById('wiRefSelectedName');
                const nb = document.getElementById('wiRefSelectedNB');
                if (n) n.textContent = name;
                if (nb) nb.textContent = code || '—';
                sel.style.display = 'block';
            }
        }

        function wiClearReferral() {
            _wiRefClient = null;
            const srch = document.getElementById('wiRefSearch');
            const sel = document.getElementById('wiRefSelected');
            if (srch) srch.value = '';
            if (sel) sel.style.display = 'none';
            const noRef = document.getElementById('wiNoReferral');
            if (noRef) noRef.checked = false;
            _wiNoReferral = false;
        }

        function wiToggleNoReferral(checked) {
            _wiNoReferral = checked;
            const refArea = document.getElementById('wiRefSearch');
            const sel = document.getElementById('wiRefSelected');
            if (checked) {
                _wiRefClient = null;
                if (refArea) { refArea.value = ''; refArea.disabled = true; refArea.style.opacity='0.5'; }
                if (sel) sel.style.display = 'none';
            } else {
                if (refArea) { refArea.disabled = false; refArea.style.opacity='1'; }
            }
        }

        // --- Products ---
        function wiFilterProducts(term) {
            wiRenderProducts(term);
        }

        function wiRenderProducts(term) {
            const grid = document.getElementById('wiProductGrid');
            if (!grid) return;

            const products = Array.isArray(window.PRICE_LIST) && window.PRICE_LIST.length > 0
                ? window.PRICE_LIST
                : [];

            if (!products.length) {
                grid.innerHTML = '<p style="color:#94a3b8;grid-column:1/-1;text-align:center;padding:20px;">No products loaded yet</p>';
                return;
            }

            const q = (term || '').toLowerCase();
            const filtered = q ? products.filter(p => (p.description||'').toLowerCase().includes(q)) : products;

            if (!filtered.length) {
                grid.innerHTML = '<p style="color:#94a3b8;grid-column:1/-1;text-align:center;padding:16px;">No products match "' + term + '"</p>';
                return;
            }

            grid.innerHTML = filtered.slice(0, 80).map((p, idx) => {
                const name = p.description || 'Product';
                const price = _wiType === 'registered' ? (p.dp || 0) : (p.cp || p.dp || 0);
                const bv = p.bv || 0;
                const safeName = name.replace(/'/g, "\'").replace(/"/g, '&quot;');
                return `<div onclick="wiAddToCart('${safeName}',${price},${bv})"
                    style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:10px;cursor:pointer;transition:box-shadow .15s;"
                    onmouseover="this.style.boxShadow='0 2px 8px rgba(0,0,0,.1)'" onmouseout="this.style.boxShadow='none'">
                    <div style="font-size:0.82rem;font-weight:600;color:#1e293b;margin-bottom:4px;line-height:1.3;">${name}</div>
                    <div style="font-size:0.85rem;color:#27ae60;font-weight:700;">${_wiFmt(price)}</div>
                    ${bv > 0 ? '<div style="font-size:0.72rem;color:#f39c12;">BV: '+bv+'</div>' : ''}
                    <div style="margin-top:6px;text-align:center;padding:4px;background:#3498db;color:#fff;border-radius:5px;font-size:0.75rem;font-weight:600;">+ Add</div>
                </div>`;
            }).join('');
        }

        // --- Cart ---
        function wiAddToCart(name, price, bv) {
            if (window.walkInCartStore && typeof window.walkInCartStore.update === 'function') {
                window.walkInCartStore.update(cart => {
                    const ex = cart.find(i => i.name === name);
                    if (ex) { ex.quantity = (ex.quantity||1) + 1; ex.total = ex.quantity * ex.price; }
                    else { cart.push({ name, price: Number(price), bv: Number(bv||0), quantity: 1, total: Number(price) }); }
                });
            } else {
                if (!Array.isArray(window.walkInCart)) window.walkInCart = [];
                const ex = window.walkInCart.find(i => i.name === name);
                if (ex) { ex.quantity = (ex.quantity||1) + 1; ex.total = ex.quantity * ex.price; }
                else { window.walkInCart.push({ name, price: Number(price), bv: Number(bv||0), quantity: 1, total: Number(price) }); }
            }
            wiRenderCart();
        }

        function wiUpdateQty(idx, delta) {
            const getCart = () => window.walkInCartStore && typeof window.walkInCartStore.get === 'function'
                ? window.walkInCartStore.get() : (window.walkInCart || []);
            const cart = getCart();
            if (!cart[idx]) return;
            const newQty = (cart[idx].quantity||1) + delta;
            if (newQty <= 0) { wiRemoveFromCart(idx); return; }
            if (window.walkInCartStore && typeof window.walkInCartStore.update === 'function') {
                window.walkInCartStore.update(c => { if (c[idx]) { c[idx].quantity = newQty; c[idx].total = newQty * c[idx].price; } });
            } else if (window.walkInCart) {
                window.walkInCart[idx].quantity = newQty;
                window.walkInCart[idx].total = newQty * window.walkInCart[idx].price;
            }
            wiRenderCart();
        }

        function wiRemoveFromCart(idx) {
            if (window.walkInCartStore && typeof window.walkInCartStore.update === 'function') {
                window.walkInCartStore.update(c => { c.splice(idx, 1); });
            } else if (window.walkInCart) {
                window.walkInCart.splice(idx, 1);
            }
            wiRenderCart();
        }

        function wiGetCart() {
            if (window.walkInCartStore && typeof window.walkInCartStore.get === 'function') {
                try { return [...(window.walkInCartStore.get()||[])]; } catch(_) {}
            }
            return Array.isArray(window.walkInCart) ? [...window.walkInCart] : [];
        }

        function wiRenderCart() {
            const body = document.getElementById('wiCartBody');
            const totalEl = document.getElementById('wiCartTotal');
            const bvEl = document.getElementById('wiCartBV');
            const cart = wiGetCart();

            if (!body) return;
            if (!cart.length) {
                body.innerHTML = '<p style="color:#94a3b8;text-align:center;padding:18px 0;">Cart is empty — add products above</p>';
                if (totalEl) totalEl.textContent = 'N$ 0.00';
                if (bvEl) bvEl.textContent = '0.00';
                return;
            }

            let total = 0, totalBV = 0;
            body.innerHTML = cart.map((item, i) => {
                const qty = item.quantity || 1;
                const price = item.price || 0;
                const lineTotal = qty * price;
                const bv = (item.bv || 0) * qty;
                total += lineTotal;
                totalBV += bv;
                return `<div style="display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid #f1f5f9;">
                    <div style="flex:1;font-size:0.85rem;font-weight:600;color:#1e293b;">${item.name}</div>
                    <div style="display:flex;align-items:center;gap:4px;">
                        <button type="button" onclick="wiUpdateQty(${i},-1)" style="width:26px;height:26px;border:1px solid #cbd5e1;border-radius:5px;background:#fff;cursor:pointer;font-size:1rem;line-height:1;">−</button>
                        <span style="min-width:24px;text-align:center;font-weight:600;">${qty}</span>
                        <button type="button" onclick="wiUpdateQty(${i},1)" style="width:26px;height:26px;border:1px solid #cbd5e1;border-radius:5px;background:#fff;cursor:pointer;font-size:1rem;line-height:1;">+</button>
                    </div>
                    <div style="min-width:80px;text-align:right;font-weight:700;color:#27ae60;font-size:0.88rem;">${_wiFmt(lineTotal)}</div>
                    <button type="button" onclick="wiRemoveFromCart(${i})" style="border:none;background:none;color:#e74c3c;cursor:pointer;font-size:1.1rem;padding:0 4px;line-height:1;">×</button>
                </div>`;
            }).join('');

            if (totalEl) totalEl.textContent = _wiFmt(total);
            if (bvEl) bvEl.textContent = totalBV.toFixed(2);
        }

        // --- Payment ---
        function wiSetPayment(method) {
            _wiPayment = method;
            const hidden = document.getElementById('wiPaymentMethod');
            if (hidden) hidden.value = method;
            ['cash','card','mobile','bank'].forEach(m => {
                const btn = document.getElementById('wiPay_' + m);
                if (!btn) return;
                if (m === method) {
                    btn.style.border = '2px solid #27ae60';
                    btn.style.background = '#e8f5e9';
                    btn.style.fontWeight = '700';
                } else {
                    btn.style.border = '2px solid #ddd';
                    btn.style.background = '#fff';
                    btn.style.fontWeight = '400';
                }
            });
        }

        // --- Review & Confirm ---
        function wiReviewSale() {
            // Validate
            const cart = wiGetCart();
            if (!cart.length) { alert('Please add at least one product to the cart before confirming.'); return; }

            if (_wiType === 'registered' && !_wiRegClient) {
                alert('Please search for and select the registered client, or switch to "New Customer".'); return;
            }
            if (_wiType === 'new') {
                const nameEl = document.getElementById('wiNewName');
                if (!nameEl || !nameEl.value.trim()) { alert('Please enter the customer name.'); nameEl && nameEl.focus(); return; }
                if (!_wiNoReferral && !_wiRefClient) { alert('Please select a referring distributor, or tick "Customer has no referral".'); return; }
            }

            // Populate confirmation modal
            const customerName = _wiType === 'registered'
                ? (_wiRegClient ? _wiRegClient.name : '—')
                : (document.getElementById('wiNewName')?.value?.trim() || 'Walk-in Customer');
            const phone = _wiType === 'registered'
                ? (_wiRegClient ? _wiRegClient.phone : '—')
                : (document.getElementById('wiNewPhone')?.value?.trim() || '—');
            const nbNum = _wiType === 'registered' ? (_wiRegClient ? _wiRegClient.code : '—') : '—';

            const cfmName = document.getElementById('wiCfmName');
            const cfmType = document.getElementById('wiCfmType');
            const cfmNB   = document.getElementById('wiCfmNB');
            const cfmPhone = document.getElementById('wiCfmPhone');
            const cfmRefRow = document.getElementById('wiCfmRefRow');
            const cfmRef  = document.getElementById('wiCfmRef');

            if (cfmName) cfmName.textContent = customerName;
            if (cfmType) cfmType.textContent = _wiType === 'registered' ? 'Registered Client (DP)' : 'New Customer (CP)';
            if (cfmNB) cfmNB.textContent = nbNum;
            if (cfmPhone) cfmPhone.textContent = phone;

            if (_wiType === 'new' && _wiRefClient && !_wiNoReferral) {
                if (cfmRefRow) cfmRefRow.style.display = 'block';
                if (cfmRef) cfmRef.textContent = _wiRefClient.name + ' (NB: ' + _wiRefClient.code + ')';
            } else {
                if (cfmRefRow) cfmRefRow.style.display = 'none';
            }

            // Products
            let total = 0, totalBV = 0;
            const cfmProducts = document.getElementById('wiCfmProducts');
            if (cfmProducts) {
                cfmProducts.innerHTML = cart.map(item => {
                    const qty = item.quantity || 1;
                    const lineTotal = qty * (item.price||0);
                    const bv = (item.bv||0) * qty;
                    total += lineTotal;
                    totalBV += bv;
                    return `<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px dashed #e2e8f0;">
                        <div><strong>${item.name}</strong> <span style="color:#94a3b8;">×${qty}</span></div>
                        <div style="font-weight:600;color:#27ae60;">${_wiFmt(lineTotal)}</div>
                    </div>`;
                }).join('');
            }
            const cfmTotal = document.getElementById('wiCfmTotal');
            const cfmBV = document.getElementById('wiCfmBV');
            const cfmPayment = document.getElementById('wiCfmPayment');
            if (cfmTotal) cfmTotal.textContent = _wiFmt(total);
            if (cfmBV) cfmBV.textContent = totalBV.toFixed(2) + ' BV';
            if (cfmPayment) cfmPayment.textContent = _WI_PAY_LABELS[_wiPayment] || _wiPayment;

            const cfmModal = document.getElementById('walkInSaleConfirmationModal');
            if (cfmModal) cfmModal.style.display = 'block';
        }

        // --- Complete Sale ---
        function wiConfirmSale() {
            const cart = wiGetCart();
            const customerName = _wiType === 'registered'
                ? (_wiRegClient ? _wiRegClient.name : 'Registered Client')
                : (document.getElementById('wiNewName')?.value?.trim() || 'Walk-in Customer');
            const phone = _wiType === 'registered'
                ? (_wiRegClient?.phone || '')
                : (document.getElementById('wiNewPhone')?.value?.trim() || '');

            let total = 0, totalBV = 0;
            cart.forEach(item => {
                const qty = item.quantity || 1;
                total += qty * (item.price||0);
                totalBV += (item.bv||0) * qty;
            });

            const saleRecord = {
                id: 'WS-' + Date.now(),
                customerName,
                customerType: _wiType,
                nbNumber: _wiType === 'registered' ? (_wiRegClient?.code || '') : '',
                phone,
                referral: (_wiType === 'new' && _wiRefClient && !_wiNoReferral)
                    ? { name: _wiRefClient.name, code: _wiRefClient.code } : null,
                paymentMethod: _wiPayment,
                items: cart.map(i => ({ ...i })),
                subtotal: total,
                total,
                totalBV,
                branch: (typeof saleRecordBranchHint === 'function') ? saleRecordBranchHint() : '',
                soldBy: window.currentUser ? (window.currentUser.username || window.currentUser.fullName || '') : '',
                createdAt: new Date().toISOString(),
                synced: false
            };

            // Save to local storage
            const key = 'dynapharm_walkin_sales';
            let history = [];
            try { history = JSON.parse(localStorage.getItem(key) || '[]'); } catch(_) {}
            history.unshift(saleRecord);
            try { localStorage.setItem(key, JSON.stringify(history.slice(0, 100))); } catch(_) {}

            // Clear cart
            if (window.walkInCartStore && typeof window.walkInCartStore.clear === 'function') {
                window.walkInCartStore.clear();
            } else { window.walkInCart = []; }

            // Refresh the walk-in sales list in the portal
            wiRefreshSalesList();

            closeModal('walkInSaleConfirmationModal');
            closeModal('walkInSaleModal');
            wiRenderCart();

            const label = _WI_PAY_LABELS[_wiPayment] || _wiPayment;
            const ref = saleRecord.referral ? '\nReferral: ' + saleRecord.referral.name : '';
            alert('✅ Sale recorded!\nCustomer: ' + customerName + '\nTotal: ' + _wiFmt(total) + ' | BV: ' + totalBV.toFixed(2) + ref);
        }

        // --- Recent Sales List Renderer ---
        function wiRefreshSalesList() {
            const container = document.getElementById('walkInSalesList');
            if (!container) return;

            let sales = [];
            try { sales = JSON.parse(localStorage.getItem('dynapharm_walkin_sales') || '[]'); } catch(_) {}

            if (!sales.length) {
                container.innerHTML = '<p style="text-align:center;color:#94a3b8;padding:24px 0;">No walk-in sales recorded yet</p>';
                return;
            }

            container.innerHTML = sales.slice(0, 30).map(s => {
                const date = s.createdAt ? new Date(s.createdAt).toLocaleString() : '—';
                const typeLabel = s.customerType === 'registered'
                    ? '<span style="background:#dbeafe;color:#1e40af;padding:2px 7px;border-radius:10px;font-size:0.75rem;font-weight:600;">DP</span>'
                    : '<span style="background:#fef3c7;color:#92400e;padding:2px 7px;border-radius:10px;font-size:0.75rem;font-weight:600;">CP</span>';
                const refBadge = s.referral
                    ? `<span style="color:#92400e;font-size:0.78rem;">↗ ${s.referral.name}</span>`
                    : '';
                const nbBadge = s.nbNumber
                    ? `<span style="color:#166534;font-size:0.78rem;">NB: ${s.nbNumber}</span>`
                    : '';
                const items = Array.isArray(s.items) ? s.items.length : 0;
                const payIcon = { cash:'💵', card:'💳', mobile:'📱', bank:'🏦' }[s.paymentMethod] || '💰';

                return `<div style="display:flex;align-items:center;gap:12px;padding:10px 16px;border-bottom:1px solid #f1f5f9;">
                    <div style="flex:1;min-width:0;">
                        <div style="font-weight:600;color:#1e293b;font-size:0.9rem;">${s.customerName || 'Unknown'} ${typeLabel}</div>
                        <div style="font-size:0.78rem;color:#64748b;margin-top:2px;">${date} &nbsp;·&nbsp; ${items} item${items!==1?'s':''} &nbsp;·&nbsp; ${payIcon} ${s.paymentMethod||'—'}</div>
                        ${nbBadge || refBadge ? `<div style="margin-top:2px;">${nbBadge} ${refBadge}</div>` : ''}
                    </div>
                    <div style="text-align:right;flex-shrink:0;">
                        <div style="font-weight:700;color:#27ae60;font-size:0.95rem;">N$ ${Number(s.total||0).toFixed(2)}</div>
                        ${s.totalBV > 0 ? `<div style="font-size:0.75rem;color:#f39c12;">${Number(s.totalBV).toFixed(1)} BV</div>` : ''}
                    </div>
                </div>`;
            }).join('');
        }

