                // Agreement Date and Signature
                if (yPos > 250) {
                    doc.addPage();
                    yPos = 20;
                }
                doc.setFontSize(12);
                doc.setTextColor(196, 30, 58);
                doc.text('Agreement Details', 14, yPos);
                yPos += 8;
                
                doc.setFontSize(10);
                doc.setTextColor(0, 0, 0);
                doc.text(`Agreement Date: ${formData.agreement_date || 'N/A'}`, 14, yPos);
